quests[85067] = { id = 85067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Paladin of the Silver Hand", description = "I said that I don't believe in fate, but I don't know if that was entirely true. My perspective has changed so much since my mortal life ended, but the longer I spend on this mission, the more I start to see patterns and connections in things. I think you know this already, but its Aeonas that has to go with you.\n\nBelieve me when I say I'd like nothing more than to leave my old friend in peace, but this is bigger than what I want. Go to Uther's Tomb and explain the situation.", sourceObjective = "Go to Uther's Tomb and explain the situation to Aeonas.", progress = "It is a faint hope, but is worth trying. If anything of Uther remains, we may yet be able to bolster the ritual and use it against our foe.", completion = "<Gregory nods at you, and then at Aeonas in turn>\n\nIt's time. {name} go speak with Chromie when you are ready.", sourceObjectiveStatus = "unverified-source-field" }
quests[85068] = { id = 85068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who Says You Can Never Go Back?", description = "The portal is ready.\n\nOnce you enter, you'll be transported to Andorhal, just after it fell.  In order to help you blend in a bit better, I've prepared some magical disguises for you. These will do for most of the denizens of the past but you'll still want to be careful to not get noticed. When you have what you need just make your way back to this place in the past. The portal should be waiting for you.", sourceObjective = "Take the portal to the Burning of Andorhal.", completion = "We made it. Steel yourself, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[85074] = { id = 85074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Burning of Andorhal", description = "I can't be sure what is waiting for us in there, but it won't be good. \n\nWe need to get in, locate the place where Uther fell and see if we can gather a few drops of his blood. From there, we need to make our way back to the inn on the west side of town and make good our escape. We should hurry, but we also need to make sure we approach this with care and respect, as my lord Uther deserves. The thought of disturbing him where he fell makes me deeply uncomfortable.\n\nLet's get this over with.", sourceObjective = "Complete your objective and escape the Burning of Andorhal.", progress = "As unsavory as this was, we've done what we came to do.", completion = "I assume we shouldn't be expecting the disguises to come back, so I think we have no choice but to fight our way out. Ready yourself, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[85087] = { id = 85087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Desperate Escape", description = "The undead have broken through and infested the west side of the city. This is going to be hard fighting, {name}. Time is against us now, so we should avoid the areas thickest with scourge. \n\nOh, I almost forgot, take this. If we somehow become separated, sound the horn and I'll make my way back to you.", sourceObjective = "Fight your way to the Inn and escape back to your own time. If you get separated from Aeonas, blow the Tarnished Horn to call him back to your side.", progress = "It's... nothing, just a scratch. I just need to catch my...", completion = "<Aeonas starts to drift off before opening his eyes suddenly and locking eyes with you.>", sourceObjectiveStatus = "unverified-source-field" }
quests[85090] = { id = 85090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Future", description = "<Aeonas winces. He is gravely wounded>  I think... this is as far as I go, {name}. It's... okay. This is... always where I belonged. I am happy to be here, with my friends... at the end.\n\nHere, take this. I forged this... to remind me. To ensure that I'd never forget the friends I lost here and that I'd always stay true to them. That's even what I called it... Truthbearer. \n\nGive it to Gregory for me. Perhaps it can help him remember more of who he is. I think you see it too... he's... changed. \n\nI...", sourceObjective = "Take the portal back to your time, and deliver Truthbearer to Gregory.", progress = "Where's Aeonas? What happened?", completion = "Tell me everything.", sourceObjectiveStatus = "unverified-source-field" }
quests[85091] = { id = 85091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cost of Victory", description = "Thank you... for bringing me this. The blade is consecrated and will cause me considerable pain to wield, but that seems a small sacrifice to make for my... my friend.\n\nGrief comes later. For now, it's time to end this. Gather your most trusted allies and go to Demon Fall Canyon. Azgaloth may not reveal himself to you immediately, but if you issue a suitable challenge, he will answer. \n\nTake the blood and use it to consecrate your weapon and destroy him. For Aeonas, and for Ada, it's time to end this.", sourceObjective = "Consecrate your weapon with the Blood of the Lightbringer and defeat Azgaloth in Demon Fall Canyon.", progress = "...", completion = "My mission is complete at long last.\n\nThis has consumed me for so long now that I haven't really considered what that victory really means.  I suppose this means our alliance is at an end and I should be on my way back to Northrend...\n\n<An uneasy silence hangs between you>", sourceObjectiveStatus = "unverified-source-field" }
quests[85092] = { id = 85092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Truthbearer", description = "Aeonas managed to see it far before I did. He saw how I've changed while on this mission. I actually feel... sadness, regret, love once again. Sadness for Ada, regret for my betrayal, and love for my friend.  I don't know exactly what this means, but I do know that I can't go back to Northrend. \n\nLordaeron, perhaps? Perhaps there are others like me there. Those that fell from the light... and are slowly finding their way back to it.  Maybe I can help them like my friend helped me.", sourceObjective = "Bid farewell to Gregory.Aeonas managed to see it far before I did. He saw how I've changed while on this mission. I actually feel... sadness, regret, love once again. Sadness for Ada, regret for my betrayal, and love for my friend. I don't know exactly what this means, but I do know that I can't go back to Northrend. \n\nLordaeron, perhaps? Perhaps there are others like me there. Those that fell from the light... and are slowly finding their way back to it. Maybe I can help them like my friend helped me.", completion = "The fact that holding Truthbearer no longer causes me pain tells me all I need to know about the path I must walk now. \n\nHowever,  I think the blade should stay with you. Aeonas would understand and I'm quite sure he would approve. The lion's share of my fighting days are likely behind me and a weapon like this deserves to be used in service of the light.\n\nGoodbye, {name}. Light be with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[85112] = { id = 85112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Depleted Scythe", description = "The scythe is twisted and emanates a strange demonic aura. Despite this, it is brittle to the touch, and you worry it would break on use. It pulls at your energy, as if testing you. A ravenous hunger lurks at the back of your mind just thinking about the scythe. Perhaps someone knowledgeable on demonic artifacts might know more.", sourceObjective = "Bring the staff to Doan Karhan in The Barrens.", completion = "This is certainly a curious artifact you've found, {name}. I believe that this staff might be saved...though it will require some effort. \n\nHmm, it might even be an excellent candidate for wrapping up some unfinished business we have.", sourceObjectiveStatus = "unverified-source-field" }
quests[85150] = { id = 85150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Only Good Bug is a Dead Bug", description = "The silithids are constantly changing, and successive generations take on new traits to improve their survival fitness. We've spotted a new kind of silithid flyer north of here, near Hive'Ashi. They're flyers, like some of the other silithid wasps, but smaller, faster, and have a blue exoskeleton.\n\nI want to know what to expect from these darters. Take out a few and report back on how tough they are.", sourceObjective = "Find and defeat four silithid darters. These are fast-moving, small silithid wasps with a blue exoskeleton.", completion = "Now we know that they can be killed. Not as tough as the other silithids, you say? Perhaps some kind of new scout form. Useful information, thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[85248] = { id = 85248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everyone Knows That Bugs Can't Fly", description = "From your reports it sounds like the darters are definitely faster, but we need to know more about them. If we can study one, perhaps we can figure out how to neutralize them more effectively.\n\nWith your hunting skills, it should be possible to incapacitate one of the darters and bring it back here so that we can learn more about it. Track one down, wound it, rope it, and bring it back here to the cage we've set up for study.", sourceObjective = "Fight a silithid darter until you weaken it, then use your Concussive Shot skill to slow it. When it frenzies, use a Tranquilizing Shot to knock it unconscious. Tie it up, drag it back to Cenarion Hold, and secure it to the  hitching post across from Commander Mar'alith's war room for further study.\n\nReturn to Commander Mar'alith in Cenarion Hold when finished.\n\nYou can learn Tranquilizing Shot from the raid on Molten Core.", progress = "Remember, weaken the darter first, then try to knock it out with concussions and tranquilizers.", completion = "Sterling work. Your skills have already showed us one way to neutralize them, and we should be able to figure out more about the darters by observing this captive.", sourceObjectiveStatus = "unverified-source-field" }
quests[85250] = { id = 85250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meeting the Menagerie", description = "While you were out, a wisp visited us looking for you. The wisp indicated that you are needed in Un'Goro Crater. The wisp said that a companion of yours discovered the location of a foe that you have been tracking for some time.\n\nThank you again for your aid here. It seems that it is time for you to move on.", sourceObjective = "Travel to Un'Goro Crater, in the south of Kalimdor, and find evidence of Van Amburgh.", completion = "You made it! I'm so glad to see you.", sourceObjectiveStatus = "unverified-source-field" }
quests[85251] = { id = 85251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Showdown at Un'Goro Crater", description = "It's time at last. It's taken everything out of me to find Van Amburgh's camp here, and I was wounded by one of his traps. His beasts are with him. Are you ready to finish this?", sourceObjective = "Travel to the camp of Van Amburgh in Un'Goro crater, in the south of Kalimdor, and defeat the dwarf and his menagerie.", completion = "It's done. Van Amburgh will commit no further atrocities.", sourceObjectiveStatus = "unverified-source-field" }
quests[85304] = { id = 85304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essence of Fire", description = "The scroll emanates a fiery energy unlike other scrolls you've found. There is a Magical Stone near Draco'dar in the Burning Steppes that may help uncover its purpose. Translate the scroll and learn its purpose before bringing your findings back to the librarians of Stormwind or Undercity.", sourceObjective = "Figure out what the unusual scroll is for and report your findings to a librarian in Stormwind or Undercity.", progress = "Have you found anything interesting?", completion = "You've found something truly interesting, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[85385] = { id = 85385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Librarian's Apprentice", description = "Your discovery of the Essence of Fire has greatly expanded our knowledge of the arcane. I have heard rumors of a similar power in Winterspring, though it is of a Frost nature. My associate in Everlook will have more information regarding the specifics.", sourceObjective = "Speak with Valxx Cracklequil in Everlook to learn about the rumors.", completion = "So you've been sent by those old bats at the library, huh? They don't like me a whole lot, saying that 'gunpowder and magic don't mix.' Pah. \n\nYeah, I know a thing or two about what you're asking about. Lucky for you I'm too busy to look into it myself.", sourceObjectiveStatus = "unverified-source-field" }
quests[85386] = { id = 85386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essence of Frost", description = "Back a while ago, I heard of some strange goings on down in Frostwhisper Gorge. It seems like those ice giants might've found some old power. I'd go investigate myself, but I'm too busy here. Bring me back anything interesting, okay? If you live, that is.", sourceObjective = "Investigate Frostwhisper Gorge for a mysterious frost power.", progress = "You're not dead yet? Interesting.", completion = "What's this? There was actually something down there?! I'm surprised those ice giants didn't turn you into an icicle, {name}. Good job.", sourceObjectiveStatus = "unverified-source-field" }
quests[85388] = { id = 85388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Foul Interference", description = "While you were gone, I heard there's something real nasty going on over in Mazthoril. It seems like your kind of thing, so go see what you can do to solve it. Those blue dragons know a lot about the arcane, maybe they'll give you something in return for it.", sourceObjective = "Stop the corruption of Mazthoril.", progress = "You're not dead yet? Interesting.", completion = "You have helped me greatly, {name}. Though I fear it pales compared to the heroics you have performed for us, I want you to have this. This staff is incomplete, but perhaps may be restored.", sourceObjectiveStatus = "unverified-source-field" }
quests[85401] = { id = 85401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Frigid Barrow", description = "Just as life springs forth from decay, so too may the unnatural come to serve the natural.\n\nThe heart can be made into a stave of shifting form, but I will need a vessel strong enough to contain its power.\n\nThere is a barrow den near Starfall Village, in Winterspring. The true entrance will only reveal itself if you are alone. \n\nWithin is a keeper who lost his way long ago; Nandieb. His stave shall be the heart's vessel. It pains me to suggest, but he is no longer the great keeper I once knew.", sourceObjective = "Find Nandieb in the barrow den near Starfall Village in Winterspring, and recover his stave. This must be done alone.", progress = "Have you recovered the stave?", completion = "The chromatic heart, and Nandieb's stave: Together, they will form the shifting staves Gla'sir and Rae'lar. Two objects of malice and destruction, transformed in service of creation and life.\n\nI bestow this power unto you, {name}, in the hope that you will continue to prove a noble steward of all life across Azeroth.", sourceObjectiveStatus = "unverified-source-field" }
quests[85413] = { id = 85413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essence of Fire" }
quests[85423] = { id = 85423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essence of Frost" }
quests[85435] = { id = 85435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Foul Interference", description = "While you were gone, I heard there's something real nasty going on over in Mazthoril. It seems like your kind of thing, so go see what you can do to solve it. Those blue dragons know a lot about the arcane, maybe they'll give you something in return for it.\n\n\n\nI heard you've been really diligent with collecting esoteric knowledge. I found these scrolls, they might come in handy.", sourceObjective = "Stop the corruption of Mazthoril.", sourceObjectiveStatus = "unverified-source-field" }
quests[85441] = { id = 85441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunderaan the Windseeker", description = "I have told you what I know, {name}. It is you who must find elementium. It is you who must destroy the Firelord's corporeal form. \n\nDo this and gain the blessing of Thunderaan.", sourceObjective = "To harness the power of the Windseeker, you must present the right and left halves of the Bindings of the Windseeker, 10 bars of Elementium, and the Essence of the Firelord to Highlord Demitrian in The Crystal Vale.", progress = "Bring the world to its knees if you must!", completion = "Even in dreams I did not dare forsee this day. \n\nGo, mortal. Speak to me again when you are ready and wish to challenge the Windseeker.", sourceObjectiveStatus = "unverified-source-field" }
quests[85442] = { id = 85442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Examine the Vessel", description = "Examine the vessel that was used to release the ephemeral storm. It is from this that the Windseeker was reborn, and now he draws upon The Crystal Vale for renewed power.", sourceObjective = "Examine the Vessel of Rebirth and return it to Highlord Demitrian", progress = "Will you harness the contained power from the Windseekers prison?", completion = "May you be protected in your crusade. May the Master bless your efforts.", sourceObjectiveStatus = "unverified-source-field" }
quests[85443] = { id = 85443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise, Thunderfury!", description = "You have defeated the Wind Seeker. Take the dormant blade and force the worshiper, Demitrian, to use the materials you provided to wake Thunderfury.", sourceObjective = "Present the Dormant Wind Kissed Blade to Highlord Demitrian.", progress = "<Demitrian is in awe of your presence.", completion = "Your might will be carried eternally on the winds of Azeroth. Take the blade and sing your storm.", sourceObjectiveStatus = "unverified-source-field" }
quests[85445] = { id = 85445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Golden Disk", description = "You have no idea what this item could be, but it's clearly an artifact of substantial power. You should find someone who can tell you more about this artifact and its true purpose.", sourceObjective = "Find someone who can tell you more about the Shimmering Golden Disk.", progress = "Please make haste, {name}.", completion = "Wait, what is that you have? That looks just like... no, it couldn't possibly be. I've only seen it in books but... it was destroyed. Surely this is not...\n\n<Garek's fixation with the object on your belt is momentarily broken and his eyes snap up to meet yours.>\n\nWhere did you get this object, {class}? Please, you must give me all of the details!", sourceObjectiveStatus = "unverified-source-field" }
quests[85446] = { id = 85446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scale of the Dragon Lord", description = "<Riosus listens as you recount your tale>\n\nYes, Garek had the right of it, this is not the true Dragon Soul... and thank the titans for that. I'd feel no more comfortable with a dimwitted mortal like yourself wielding an artifact that powerful than I would the Lord of Blackrock himself. Regardless, this is still dangerous and we should see to its disposal. The original Dragon Soul was not easy to destroy. Come, let us speak of options for the disposal of this lesser simulacrum.", sourceObjective = "Speak with Riosus and form a plan for how to dispose of the Simulacrum of the Dragon Soul.", progress = "...", completion = "Good work, {class}. Well, for a mortal in any case. Now, give me the dragon scale. With this we have the tools we need to unlock the simulacrum's secrets and, should it be again turned against us, destroy it.\n\nOh, you look surprised. Did you think that we'd rush to destroy this gift without fully understanding what its capable of, or how it could be used against our enemies? Fool.", sourceObjectiveStatus = "unverified-source-field" }
quests[85447] = { id = 85447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grim Batol", description = "Nefarian has long been engaged in experimentation involving the five dragonflights, and it seems this \"simulacrum\" of the Dragon Soul was one such experiment. I shudder to think of what could come of him successfully emulating even a fraction of the power of the true Dragon Soul. Please, seek out agents of the red dragons near the ruins of Grim Batol. \n\nI will enchant the simulacrum you carry to mark you as a friend of the red flight.", sourceObjective = "Bring the Simulacrum of the Dragon Soul to the leader of the dragon host near the entrance to the fortress of Grim Batol.", progress = "Who are you and why do you dare come before me, mortal?", completion = "You bear the mark of an agent of Korialstrasz but as a stranger I still have no choice but to mistrust you, mortal. Mark or no, I advise that you tread carefully, lest I allow my dragonkin to incinerate and devour you.", sourceObjectiveStatus = "unverified-source-field" }
quests[85453] = { id = 85453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Good Deed Goes Unpunished", description = "With that, I fear that you've outlived your usefulness. Don't worry though, I'd not dream of letting your service go unrewarded, so I'm going to bestow the honor of being devoured by me in my true form. It's really quite the honor, {class}.", sourceObjective = "Defend yourself against Riosustrasz!", completion = "Please, {class}. Accept my apologies for this mistreatment. You've done us a great service. Not only have you dealt a crushing blow against the black dragonflight, but you've recovered a dangerous weapon that could have been used to dominate all dragonkind. \n\nI assure you, unlike my wayward brother, I pay the debts that are owed to my flight.", sourceObjectiveStatus = "unverified-source-field" }
quests[85454] = { id = 85454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Just Reward", description = "You've done much to defend our brood, {class}. It seems fitting that we repay you with a gift that you may use to continue to defend others. Speak with me when you are ready and we'll destroy this false Dragon Soul together. I believe that I can harness some of the energy released as the simulacrum's magic dissipates along with a bit of my own magic to create something special for you.", sourceObjective = "Speak with Krasus to destroy the Simulacrum of the Dragon Soul and receive your reward.", completion = "I can't say I've ever used magic to craft a shield before but the results are rather impressive, if I could be so vainglorious as to say so myself.\n\nWith this, our business is concluded and I must be on my way. Use this well in the defense of those most in need of your protection. \n\nFarewell, mortal.", sourceObjectiveStatus = "unverified-source-field" }
quests[85455] = { id = 85455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blood of the Lightbringer", description = "Your hand trembles slightly as you hold the small vial of blood. Aside from the inscription on the label, you can feel a warmth and energy radiating from the sample. Could this truly be the blood of the legendary hero, Uther the Lightbringer? You should find someone who can verify the authenticity of this sample.", sourceObjective = "Find someone who can tell you more about the Blood of the Lightbringer. \n\n(Please note that you need to have previously completed the quest \"Plaguelands Rendezvous\" to be able to hand in this quest)", progress = "Peace be with you, {class}.", completion = "Wait, what is that you have there? \n\n<High Priest Thel'danis' eyes go wide as he examines the reliquary>\n\nSurely this cannot be. How would the black dragons obtain a sample of Lord Uther's blood? \n\nIf this is genuine, this would become a relic of profound importance. Let us speak further on this.", sourceObjectiveStatus = "unverified-source-field" }
quests[85457] = { id = 85457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just What Was Needed", description = "I can already tell that you intend to bring the blood to Gregory. Good. My judgement has been questionable at best, and this was always a younger paladin's game that I've just been playing at.\n\nI'm still not sure of how to feel, but I'm certainly happy to see that you've grown into the paladin you were always meant to be.", sourceObjective = "Take the Blood of the Lightbringer to Gregory in Caer Darrow in Western Plaguelands.", progress = "Yes, {name}?", completion = "I wasn't expecting to see you back here again, at least not this soon. What is it?", sourceObjectiveStatus = "unverified-source-field" }
quests[85458] = { id = 85458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkwhisper Gorge", description = "This is... incredible. I'm far too pragmatic to believe in fate, but this is certainly a fortuitous turn of events. With this, I think we have everything we need to finish the ritual and destroy the orb for good. As with any good ritual, location is key. Are you familiar with Darkwhisper Gorge in Winterspring? It's an accursed, demon-infested place, but that is where we must go to finish this. \n\nI will gather the orb and the remaining materials and meet you there. The end of my mission is near at hand!", sourceObjective = "Meet Gregory at Darkwhisper Gorge, in Winterspring.", progress = "You made it, good. Be on your guard, {name}.", completion = "I know that this was a bit out of the way, but we needed an area where the barrier between our reality and the nether is thin, with a large concentration of latent arcane energy. Last time we chose Felwood before because of its proximity to Mount Hyjal. For this ritual I will take no chances, and I wanted to get as close to the dormant Well of Eternity as possible.\n\nI can already tell this is the perfect place. I can nearly feel the energy on the air. Come, let's begin.", sourceObjectiveStatus = "unverified-source-field" }
quests[85468] = { id = 85468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soul of Mischief", description = "Looking at the curious scythe you've brought in, I believe we need to provide it souls in order to restore it. Let's start with imps. I have an associate in the Eastern Plaguelands near Northdale that may be able to help you. Mention my name and he should be more amenable. I'll meet you in Light's Hope Chapel after you are done.", sourceObjective = "Convince Xirath near Northdale in Eastern Plaguelands to help you gain a Soul of Mischief and use it on the Depleted Scythe of Chaos.", progress = "Is everything going well?", completion = "Great work, {name}, the scythe appears to be regaining power. Oh, Xirath? Pity he double-crossed us in the end. I'll have to find a new associate. Let's try increasing the potency of the soul next time.", sourceObjectiveStatus = "unverified-source-field" }
quests[85480] = { id = 85480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Procrastimond's Gratitude", sourceObjective = "You are a remarkable mortal, little one. The gift of foresight is not common among your kind.\n\nI must warn you, though. Such knowledge can influence events, even unintentionally. It is quite possible your future will take a different path than the one written in my library.\n\nI found this book which does not appear to belong in my collection. Please accept it, with my thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[85485] = { id = 85485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soul of the Void", description = "The scythe is progressing nicely. The next soul you should try adding is that of a Voidwalker. I know of a particularly powerful one that is lingering despite its master dying nearby. It should make for a good addition.", sourceObjective = "Find the Voidwalker near Corin's Crossing in Eastern Plaguelands and add its soul to the scythe.", progress = "Is everything going well?", completion = "Excellent, {name}. Are you ready for the next stage of restoration of this scythe?", sourceObjectiveStatus = "unverified-source-field" }
quests[85486] = { id = 85486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soul of Enthralling", description = "Your next task is a much trickier one that involves those Fel portals that have been appearing around. I've heard that when mages use special scrolls, they summon powerful Fel Interlopers. The scourge in Plaguewood seem to be up to a similar trick. Use the demon they are attempting to summon in the same way for the next soul shard.", sourceObjective = "Use a Glowing Scroll of Spatial Mending on a Large Fel Rift to summon a Fel Interloper and obtain its soul.", progress = "Is everything going well?", completion = "You have truly gone above and beyond, {name}. Just one more soul and the scythe will be ready for its final test.", sourceObjectiveStatus = "unverified-source-field" }
quests[85501] = { id = 85501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of Chromaggus", description = "The heart of the once-fearsome Chromaggus rests in your hands. Its kaleidoscopic hues are as exquisite as they are grotesque. You sense a great power within the heart; something beyond your comprehension. To know more will require the aid of one much more powerful and ancient than yourself.", sourceObjective = "Find someone who can understand the power of the Chromatic Heart.", progress = "What have you brought me, little one?", completion = "This heart is a terrible, aberrant, thing. However, its power could possibly be reformed to serve better ends.", sourceObjectiveStatus = "unverified-source-field" }
quests[85505] = { id = 85505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soul of Devouring", description = "This soul should be an interesting one. While you were gone I've heard that a rogue felhound has been preying on some mages near Blackwood Lake. Take this special soul shard - it should amplify the effects of arcane magic cast on you. That felhound won't be able to resist it.", sourceObjective = "Find the mages near Blackwood Lake and have them cast spells on you until the felhound appears.", progress = "Is everything going well?", completion = "The scythe is ready at last. Just one more trial, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[85506] = { id = 85506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Test", description = "I should reveal my true purpose now, {name}. I believe this scythe can help put a stop to Des'Altek once and for all. Meet me at Demon Fall Canyon in Ashenvale so that we can use him as the final soul needed to restore the scythe to full power.", sourceObjective = "Obtain Des'Altek's soul from Demon Fall Canyon and use it to finish restoring the scythe.", progress = "Is everything going well?", completion = "Thank you for helping me, {name}. You have done well. Please keep the scythe as a token of my gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[85507] = { id = 85507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Wayward Friend", description = "I'm glad you are here, {name}. We've got word that a traveler matching the description of our friend Aeonas has been seen near Chillwind Camp, heading in the direction of Sorrow Hill. \n\nAfter what happened in felwood I wanted to give him space  but there are those in the order who still distrust him, and at some point he's going to need to come in from the cold to explain why he withheld his prolonged involvement with a known agent of the Lich King. Go and find him, see if you can convince him to come in.", sourceObjective = "Find Aeonas near Sorrow Hill in the Western Plaguelands.", progress = "You should hurry and bring Aeonas back to us. The longer he waits to come in to explain himself, the worse this all looks.", completion = "I had a feeling you'd turn up sooner or later. Sorry to disappoint you, but its not quite time for me to come back yet. That's the best part about being a \"former\" member of the Silver hand; I don't answer to anyone in the order anymore. \n\nAt some point I'll come back but for now please tell Katherine that I've acknowledged her request but I am not ready just yet.", sourceObjectiveStatus = "unverified-source-field" }
quests[85508] = { id = 85508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Wayward Friend", description = "You look like you've grown strong since last we met. I'm very glad. If there's anything I've done right in my life, its saving your life in Felwood and that is a comfort to me.\n\nAnyway, best be getting going back to Katherine now, unless there was anything else you needed to ask me?", sourceObjective = "Speak with Aeonas before heading back to Stormwind to let Katherine know his answer.", completion = "{name} thank the light you are here! The vault has just been robbed and the Mannoroc Echoing Orb has been stolen!", sourceObjectiveStatus = "unverified-source-field" }
quests[85509] = { id = 85509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Theft Echoing Orb", description = "Please make your way over to the southeastern area of the canals and speak with the Vaultkeeper there, Julien Faranister. He can tell you what he knows. Learn what you can about the crime. There were a lot of people who would have wanted to steal that orb, so gathering as much information as we can now while the crime scene is fresh is vital.", sourceObjective = "Speak with Vault Keeper Faranister in the Canal District of Stormwind and return to Katherine when you've learned what you can.", completion = "That isn't much to go on, but its better than nothing I suppose. \n\nI'm interested to hear what you learned in your meeting with Aeonas, but I am afraid this matter takes priority at the moment. Let's talk about our current lead.", sourceObjectiveStatus = "unverified-source-field" }
quests[85510] = { id = 85510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Solid Lead", description = "This is undoubtedly a burning blade medallion, which suggests legion cult involvement. As for where to start, you might try to head over to the taverns in the city and try to shake down some of the more unsavory types for information.  \n\nIt's not much, but its a start.", sourceObjective = "Explore some of the more disreputable parts of Stormwind for information on who may have been plotting to rob the vault.", completion = "You look like someone who just lost something...\n\nI suspected you'd end up here sooner or later looking for it. To your credit, you made it faster than I expected.", sourceObjectiveStatus = "unverified-source-field" }
quests[85511] = { id = 85511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plaguelands Rendezvous", description = "Of course I expected you to find me here. Why do you think I left those cultist's corpses for you to find in that vault? \n\nBefore you get too worked up; yes the orb is safe. More safe than this city, apparently. If I had entered the vault just a few moments later the orb would have been long gone.\n\nI've said enough for now and this tavern has ears. Find me on the Island of Caer Darrow in Western Plaguelands. You'll get answers when you arrive.", sourceObjective = "Find Ada Darkhardt at Caer Darrow in Western Plaguelands.", progress = "Let's speak, {name}.", completion = "I sense the end is in sight. Hopefully we can find a suitable replacement for your blood, and be done with this business once and for all.\n\nIn any case, you came all this way in good faith and didn't try to kill me so I appreciate that. Here, take this as a token of my appreciation. It's not much, but it served me well... in another life. Hopefully it can be a boon to you as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[85521] = { id = 85521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking the Trapper", description = "The note that you've found appears to be a receipt for the suppression traps surrounding the lair of Broodlord Lashlayer. The note states that if the Broodlord needs more Suppression Traps, he can purchase them from the camp of the seller, near the west side of the Burning Steppes, just south of the road to the Altar of Storms. The note also says that the seller may be moving on soon, so the Broodlord should hurry if he wants more traps.", sourceObjective = "Find the abandoned camp on the west side of the Burning Steppes, south of the road to the Altar of Storms, and investigate the area.", progress = "The abandoned camp should offer some clues.", completion = "Perhaps we can work together. I am still following other leads, but we can share clues to track down this offender against the natural world and stop him from causing more harm.", sourceObjectiveStatus = "unverified-source-field" }
quests[85525] = { id = 85525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Night in Winterspring", description = "Just having a tent won't be enough to survive the night in a Winterspring storm. You'll need food, furs, and fire to keep warm, or you'll freeze to death while you wait. Fortunately, nature provides everything you'll need, and you can forage for it all right here.", sourceObjective = "Collect bear meat, warm fur, and dry wood. Bring the materials back to your campsite to construct a shelter so that you can survive the storm.\n\nIf you lose your foundation, make a new one with your survival supplies and bring the materials there.", progress = "You'll need enough food, fur, and fire to survive the night without freezing to death.", completion = "With the additional supplies, it should be possible to camp through the storm.", sourceObjectiveStatus = "unverified-source-field" }
quests[85555] = { id = 85555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heavy Metal", description = "The large flat disc of elementium you hold before you seems to thrum with elemental energy. When you hold it you can almost hear the elemental spirits whispering to you. You aren't sure what use you can find for this, but the connection you feel to it is instantaneous.  \n\nWith a little work from a sufficiently talented smith able to work with the mysterious metal known as elementium, you suspect that this could be made into a weapon or piece of armor.", sourceObjective = "Find someone who can work with exotic metals and is willing to help you crate something special with this chunk of elementium.", progress = "What's that you've got there?", completion = "Wow! That's quite the hunk of metal you got there, {class}. \n\nElementium you say? How'd ya get your mitts on something like this? Actually, it's probably better if I don't know. Anyway, I know a guy who might be able to help you make something good with it. Name's Krixix. Last I heard he was working up in Blackrock Mountain for a guy named, uh, Vick I think. Not sure what they got him doing but they aren't exactly knitting sweaters up in that mountain, if you catch my drift.", sourceObjectiveStatus = "unverified-source-field" }
quests[85556] = { id = 85556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Particular Set of Skills", description = "Krixix is a genius for sure, but he may not be too friendly if you just storm into that mountain demanding his help, to say nothing of the goons that place is likely crawling with. You'll probably want to find a way to get to him without burning the place down along the way which is likely to be pretty tricky. \n\nIf you can figure out a way to get in there without stabbing, shocking, or burning anyone that is probably a good start. I've got no real ideas myself on how to do that though, so good luck!", sourceObjective = "Find a way to get into Blackwing Lair and speak with Master Elemental Shaper Krixix without engaging him in combat.", progress = "Shouldn't you be working,  bub?", completion = "Whaddya want, can't you see I'm busy here? Wait, where'd you get that hunk of slag? I swear if those half-wit gobs down in the lab are being wasteful with my product, I'm gonna lose it!\n\nYeah yeah, I'm sure I could make it into something good for you, but I'm behind schedule and Vick ain't known for his patience. Now, unless you can help me clone myself or grow a bunch of extra arms, beat it. I got work to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[85557] = { id = 85557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Efficiency Is Priority One", description = "Actually, I just gave myself an idea. You see, the biggest problem when workin' with elementium is keeping the forge hot enough. If I had something that I could use to keep the fire goin' full strength longer, I wouldn't have to waste as much time as I do stoking it. \n\nIf you can find me a magical means to keep my forge hot, I could free up a bit of my time for side hustles like your little request. Now go, beat it. See what you can rustle up for me.", sourceObjective = "Find a suitable power source to keep Master Elemental Shaper Krixix's elementium forge run more efficiently.", progress = "What are you talkin' to me for? Scram.", completion = "Wow! This is perfect!\n\nYou'd think that Vick could have used some of that magic of his to fix this problem for me, being the son of Deathwing and all. Between you and me though, he's got that \"complacent second generation management\" energy. Useless. \n\nAt any rate... let's get crackin' on this.", sourceObjectiveStatus = "unverified-source-field" }
quests[85558] = { id = 85558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Commit to Quality", description = "I've been thinking about what to do with that hunk of metal and I think I've got the perfect thing for it. Give me just a few minutes here and I can whip it up for you.", sourceObjective = "Watch Master Elemental Shaper Krixix craft your item.", completion = "There she is. Isn't she a beauty? Don't be fooled by how long it took for me to whip this bad boy up. I only made it LOOK easy. I assure you, this is a masterpiece. \n\nI even think it's my finest work. Of course, everything I make is my finest work. Well, that was a fun distraction, but I've got to get back to work. See ya around.", sourceObjectiveStatus = "unverified-source-field" }
quests[85559] = { id = 85559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Night Falls", description = "If you'll walk with me, I have one last thing to show you.", sourceObjective = "Walk with Estelenn and see what she has to show you.", progress = "I promise this won't take long.", completion = "It's over at last. Finally, I can rest.\n\nVan Amburgh killed me some time ago, you see. But I could not pass on while he inflicted such suffering on his animal minions. I had to find someone who understood animals like I did, who lived like I did, and I found you.\n\nI must go, but before I do, I have one last thing for you. I was buried here, and I want you to take my swords, the last thing I left behind.\n\nGo with the green.", sourceObjectiveStatus = "unverified-source-field" }
quests[85595] = { id = 85595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Presence of Might", progress = "Zanza can create the ancient troll enchantments with the right components.\n\nThe first is a primal Hakkari idol that must be taken from the most powerful of the Hakkari lieutenants: Jin'do and the Bloodlord.\n\nThe second is a punctured voodoo doll. These can be found in the piles of refuse that litter this foul place. Look inside the jinxed hoodoo piles.\n\nBring me these things and I will create a powerful enchantment for you!", completion = "Use it well, {class}. Show the Hakkari no mercy!" }
