quests[85603] = { id = 85603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vodouisant's Vigilant Embrace", progress = "Zanza can create the ancient troll enchantments with the right components.\n\nThe first is a primal Hakkari idol that must be taken from the most powerful of the Hakkari lieutenants: Jin'do and the Bloodlord.\n\nThe second is a punctured voodoo doll. These can be found in the piles of refuse that litter this foul place. Look inside the jinxed hoodoo piles.\n\nBring me these things and I will create a powerful enchantment for you!", completion = "Use it well, {class}. Show the Hakkari no mercy!" }
quests[85604] = { id = 85604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Unmarred Vision of Voodress", progress = "<Maywiki points to your talisman.>\n\nLook at it, {name}! It's come alive. The spirits dance around the orb.\n\nGive it to Maywiki so she can make one last adjustment.", completion = "One day, {name}, you will be able to use this orb to communicate directly with me. Whenever this battle with Hakkar be over and Maywiki go home. Let us call to the spirits and ask them for that day to come soon." }
quests[85605] = { id = 85605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Augur's Bracers", description = "The augurs of our tribe are revered for their gifts of the divine sight, ya mon.  They ain't a witch doctor; they spend their time castin' bones or readin' the leaves for insight - not hexin' people.  As a shaman, you already know somethin' about the power of augury; we Zandalar prize the insight they give to the tribe.\n\nBring me an offerin' of the Paragons of Power from inside Zul'Gurub and prove your worth to us.  Do this for us, and I'll give ya some bracers that our augurs prize above all others!", sourceObjective = "Bring Maywiki of Zuldazar a Primal Hakkari Armsplint. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nMaywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale.", progress = "Got the Paragons of Power from Zul'Gurub that I need?  These bracers are well worth any effort ya be needin' to make!", completion = "It seems ya got a bit of the Zandalar augur in ya.  We know about the deeds you've been doin' in Zul'Gurub on our behalf mon.  These Paragons of Power will go a long way to helpin' out the Zandalar tribe - a tribe, I might add, ya can call upon as friends.  Take these bracers, {name}; ya earned them and then some!", sourceObjectiveStatus = "unverified-source-field" }
quests[85606] = { id = 85606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Augur's Belt", description = "Augurs know the mojo of the elements, mon.  They use it as a means to guide the tribe to glory.  In the dark days after the Gurubashi Empire ripped itself up, our augurs led us to our safe haven in the South Seas.  They've also led us back here to the Vale, right back to the heart of evil brewin' in Zul'Gurub.\n\nBring me an offerin' of the Paragons of Power from inside Zul'Gurub and prove your worth to us.  Do it and I'll give ya a belt that our augurs use - one with powerful mojo inside it!", sourceObjective = "Bring Maywiki of Zuldazar a Primal Hakkari Girdle. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nMaywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale.", progress = "The Paragons of Power are what I need mon - we'll tap the power right out of them in our fight against the evil from Zul'Gurub.  Do ya have them for me?", completion = "I can smell the scent of vanquished evil on ya, {name}.  It's a sweet smell mon... one I think you know quite well.\n\nI know it's no small feat to have brought me the Paragons of Power required for the belt.  Your deeds have not only honored the tribe, but also honored yourself amongst my tribe.  Here ya are - take the augur's belt and don it as your own!", sourceObjectiveStatus = "unverified-source-field" }
quests[85607] = { id = 85607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Augur's Hauberk", description = "The augurs of the Zandalar all wear a distinctive chest piece called a hauberk.  It's fitted with the finest of silks and cloths, interwoven with strong chain.  It's a symbol of not only their divinity, but also of their authority, mon.  It's never wise to cross one whose life is devoted to speakin' with the spirits...\n\nBring me an offerin' of the Paragons of Power from inside Zul'Gurub and prove your worth to us.  Do it and I'll give ya one of the finest hauberks our augurs would ever hope to wear!", sourceObjective = "Bring Maywiki of Zuldazar a Primal Hakkari Tabard. You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nMaywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale.", progress = "The Paragons of Power are a key source of magic power - the same kind of power that goes into makin' the augur's hauberk.  Bring me what I need, and I'll be able to share the finest of vestments any Zandalar augur would be wantin' as their own.", completion = "I know what ya had to go through to bring me the Paragons of Power, {name}.  It wasn't easy, mon - defeatin' the evil that seeps out of Zul'Gurub like a foul ooze - but now that it is all said and done, I can easily say that you'll be revered amongst the Zandalar for ages to come!\n\nHere - take the augur's hauberk and wear it with pride!", sourceObjectiveStatus = "unverified-source-field" }
quests[85608] = { id = 85608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pristine Enchanted South Seas Kelp", progress = "{name}! It been a long time since I seen you. Did you know that King Rastakhan himself be givin' me the order to add the final bit of mojo and magic to your talisman? It be true, mon! I wouldn't have believed it had I not seen it with me own eyes. Give it here.", completion = "{name} mon, it been a good journey. Keep on with the killing and suppressing of Hakkar and he minions." }
quests[85609] = { id = 85609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Haruspex's Bracers", description = "A haruspex is a key member of our tribe; you'll be wise to listen to their portents.  By communion with animals and givin' them up to the spirits when needed, they give us divine guidance.  In times past, the haruspex's insight and wisdom gave us an edge in the wars against the splintered tribes of the Gurubashi.\n\nBring me an offerin' of the Paragons of Power from inside Zul'Gurub and prove your worth to us.  Do this, and I'll give ya bracers that any haruspex of the Zandalar would want.", sourceObjective = "Bring Maywiki of Zuldazar a Primal Hakkari Stanchion. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nMaywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale.", progress = "Have ya got the Paragons of Power from Zul'Gurub?  These bracers are worth the effort, {name}.  Trust me mon!", completion = "Ah, I can sense the power comin' from these Paragons of Power, {name}.  Ya proved to be someone we in the tribe can call \"friend.\"  A deal is a deal, {name}... behold the power of the haruspex's bracers!", sourceObjectiveStatus = "unverified-source-field" }
quests[85610] = { id = 85610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Haruspex's Belt", description = "We Zandalar know not of druidic ways; nature is to be shaped by our need, not the other way around.  Still, a haruspex is the one of us most in tune with nature, and rightly so.  To give up the ghost of a beastie is to know what it is to be one of them.  That is the real power of nature.\n\nBring me an offerin' of the Paragons of Power from inside Zul'Gurub, proving yourself to us.  Do this, and I'll give ya a powerful item - a belt used by many of the Zandalar's haruspices.\n\nStrong mojo, ya mon!", sourceObjective = "Bring Maywiki of Zuldazar a Primal Hakkari Sash. Maywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale. You must also be Honored with Zandalar.", progress = "Got the Paragons of Power from Zul'Gurub I need?  The haruspex's belt will be yours if ya have them.", completion = "I thank you - the latent power in these items will be treasures unto themselves, you betcha.  Not only have ya done as I've asked of ya, but you've also proven to be honorable to us here in the tribe.  As promised, here is your reward!", sourceObjectiveStatus = "unverified-source-field" }
quests[85611] = { id = 85611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Haruspex's Tunic", description = "The ultimate symbol of a haruspex's power is what they wear, {name}.  Of these, the tunic symbolizes the connection between themselves and the divine wisdom they seek.  It often weaves parts of the beasties they sacrifice into the tunic; this reminds them of the connection they have to their gifts.\n\nBring me an offerin' of the Paragons of Power from inside Zul'Gurub and prove your worth to us.  Do this, and a tunic seeping with the true power of a haruspex is yours.", sourceObjective = "Bring Maywiki of Zuldazar a Primal Hakkari Tabard. Maywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale. You must also be Revered with Zandalar.", progress = "Got the necessary Paragons of Power from Zul'Gurub?  The haruspex's tunic is well worth any effort ya be needin' to make.", completion = "Impressive... you've successfully collected the required Paragons of Power, {name}.  Your accomplishments in Zul'Gurub for the Zandalar are legendary; hence forth, you'll be revered amongst the tribe.  Here is your tunic, mighty {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[85612] = { id = 85612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rage of Mugamba", progress = "King Rastakhan sends his regards, Master {name}. Such an honor has never been given to one outside the Zandalar tribe.\n\n\n\nGive me your talisman so that I may enhance it once more. Know that the Rage of Mugamba is now intrinsically connected to your very soul.", completion = "Zul'jin would be envious, {class}. Go forth and conquer!" }
quests[85613] = { id = 85613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Vindicator's Armguards", description = "Vengeance is power.  The Zandalar vindicator is such power.  The tribe has many enemies.  The vindicator exacts retribution on them.  No crime against us is unpunished.  The vindicator delivers this punishment.  Our enemies fear our vengeance.  They should.  They forever will.\n\nBecome one of our vindicators.  Seek the Paragons of Power inside Zul'Gurub.  Slay the minions of Hakkar and claim vengeance in the tribe's name.  You will be rewarded.", sourceObjective = "Bring Jin'rokh the Breaker a Primal Hakkari Armsplint. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nJin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.", progress = "Have you brought the Paragons of Power?  Has vengeance been claimed in the name of the Zandalar?", completion = "You have wrought much vengeance today.  You have taken on the visage of the vindicator.  You have brought the Blood God's minions to their knees.\n\nTake this.  It will fuel your vengeance for the future.  You are a friend to the Zandalar now.", sourceObjectiveStatus = "unverified-source-field" }
quests[85614] = { id = 85614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Vindicator's Belt", description = "The ultimate vengeance waits within Zul'Gurub.  Hakkar must not rise again.  Hakkar destroyed the Gurubashi Empire from within.  No sacrifice was enough.  The trolls are a shadow of former glories.  I know this is because of Hakkar.\n\nBecome the vindicator you were meant to be.  Wreak havoc on the minions of evil.  Zul'Gurub must taste Zandalar vengeance.  Bring me proof in the Paragons of Power.  You will receive the vindicator's belt.  You will receive real power.\n\nGo.", sourceObjective = "Bring Jin'rokh the Breaker a Primal Hakkari Girdle. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nJin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.", progress = "Have you brought the Paragons of Power?  Have you struck down the enemies of the tribe?  Hakkar must know the wrath of the vindicator!", completion = "The way of the vindicator is now known to you.  You have brought honor to the tribe.  You have brought honor to yourself.  You have brought pain to our enemies.\n\nThe vindicator's belt is yours.  You are surely becoming one with the way of the vindicator.", sourceObjectiveStatus = "unverified-source-field" }
quests[85615] = { id = 85615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Vindicator's Breastplate", description = "The vindicator's symbol of power is the breastplate.  It is forged with powerful mojo.  It is trusted only to those we revere.  It is the Zandalar symbol of vengeance.\n\nTo become a vindicator is to become vengeance.  Take the Paragons of Power we need from Zul'Gurub.  Bring them to us.  We will take the mojo stolen from us.  We will make the minions of Hakkar pay.  We will reward you with the vindicator's breastplate.\n\nGo.  Be our vengeance, {name}.", sourceObjective = "Bring Jin'rokh the Breaker a Primal Hakkari Kossack. You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nJin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.", progress = "Your presence means victory?  Do you have the Paragons of Power?  Tell me of the vengeance you have wrought today!", completion = "You are to be revered for your deeds.  The tribe rewards its heroes.  Zul'Gurub has tasted Zandalar vengeance like never before.\n\nYour deeds will herald the deeds of others to come.  They will look upon you as a sign of real power.  They will look upon you as vengeance personified!", sourceObjectiveStatus = "unverified-source-field" }
quests[85616] = { id = 85616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The All-Seeing Eye of Zuldazar", progress = "If only we had ten-thousand more like you, {name}. The armies of Hakkar would be scattered to the wind in the blink of an eye.\n\n\n\nAlas, the Eye is ready to realize its full potential. Give it to me.", completion = "Smite them all and let Hakkar sort them out..." }
quests[85617] = { id = 85617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hero's Brand", progress = "The King has acknowledged your existence, {class}. You are the first of your kind to be accepted by Rastakhan as a true ally of Zandalar.\n\nYou will be rewarded greatly for your efforts. Present your brand and I shall apply the final amplification.", completion = "Vigilance, honor, loyalty, bravery... You embody all of these traits and so shall your brand." }
quests[85618] = { id = 85618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Freethinker's Armguards", description = "You are a heathen.  Heathens have a place in the tribe.  Heathens are freethinkers of Zandalar.  Freethinkers do not fear oppression.  Freethinkers die for what they believe in.  We know you would die for what you believe in.  This earns our acknowledgement.  This earns you a chance to prove yourself further.\n\nWe must have the Paragons of Power.  Go to Zul'Gurub.  Kill the minions of Hakkar.  Return when you have what I seek.  Claim the first battle gear of a Zandalar freethinker.\n\nGo.", sourceObjective = "Bring Jin'rokh the BreakerPrimal Hakkari Bindings. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nJin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.", progress = "You have returned?  Do you have the Paragons of Power?  Are you wasting my time?\n\nI hope not, heathen.", completion = "You do much to honor us.  Your hands drip with the blood of Hakkar's minions.  You are a friend to the tribe.\n\nWear these bracers.  They are the freethinker's armguards.  This is what I mean about real power.", sourceObjectiveStatus = "unverified-source-field" }
quests[85619] = { id = 85619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Freethinker's Belt", description = "Your beliefs are alien to us, heathen.  Ancient Zandalar were once branded as heretics.  This was when the Gurubashi Empire was strong.  Heathens dared to challenge the priest of Hakkar.  Heathens then were hunted and killed as vermin.  Those heathens never wavered in their fight against the Blood God.  We honor the price they paid.  They are the freethinkers.\n\nDestroy the minions of Hakkar in Zul'Gurub.  Bring me the Paragons of Power I seek.  Success will be greatly rewarded.\n\nGo.", sourceObjective = "Bring Jin'rokh the Breaker a Primal Hakkari Shawl. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nJin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.", progress = "Your presence means victory?  Do you have the Paragons?  Are you dripping in the remains of your enemies?", completion = "Your honor is assured in the tribe.  You claim many deaths in Zul'Gurub.  Enemies fall before your convictions.  Enemies fall before your power.\n\nThis is the freethinker's belt.  It is a symbol of honor.  It is powerful mojo.  It is now yours.", sourceObjectiveStatus = "unverified-source-field" }
quests[85620] = { id = 85620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Freethinker's Breastplate", description = "Battle gear gives you power in the tribe.  The freethinkers are honored in this way.  They are zealots.  They imbue their breastplates with powerful mojo.  If their beliefs falter in the face of the enemy, their breastplate will not.\n\nYou must be revered amongst us to possess such a breastplate.  Go to Zul'Gurub.  Take the Paragons of Power I need.  Take the Paragons most painfully from the fools inside.  Bring them to me.  Prove your worth as a freethinker once and for all.", sourceObjective = "Bring Jin'rokh the Breaker a Primal Hakkari Tabard. You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nJin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.", progress = "Do you have the Paragons?  They have mojo inside them.  We must have them.  You will aid us.", completion = "You have done what few ever could.  You have brought the minions of Hakkar to their knees.  You have shown them what a freethinker can do.  You have shown us how a heretic could be revered in the tribe.  You have more than real power.  You ARE real power.\n\nTake the breastplate, freethinker.  Crush those who oppose you.", sourceObjectiveStatus = "unverified-source-field" }
quests[85622] = { id = 85622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Confessor's Wraps", description = "We Zandalar invest power in those who speak with the authority of divinity.  Our priests are more than just healers - they are our confessors.  Evil comes both from outside threats - such as Hakkar - and from within the tribe.  Our confessors act as the judges amongst us, preserving us from the same evil that devoured the Gurubashi from inside itself.\n\nGo to Zul'Gurub and bring back the Paragons of Power from the Gurubashi.  Learn what it means to be the confessor, and preserve us from evil.", sourceObjective = "Bring Al'tabim the All-Seeing a Primal Hakkari Stanchion. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.", progress = "Back from Zul'Gurub, are you?  Have you succeeded in retrieving the Paragons of Power from the minions of Hakkar?", completion = "Outstanding, {name}!  This was no small feat bringing these to me.  No doubt you've acted as our tribe's confessor today in preserving ourselves against the threat of Hakkar.  These wraps are befitting a friend of the tribe such as you!", sourceObjectiveStatus = "unverified-source-field" }
quests[85623] = { id = 85623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Confessor's Bindings", description = "Shortly after the fall of the Gurubashi, we Zandalar almost succumbed to a final defeat from evil within our own tribe.  It was then that the confessors amongst us arose, preserving the tribe by banishing out those who would destroy their own kind.  They not only keep us in tune with the spirits, but they also preserve the flesh.\n\nGo forth into Zul'Gurub and witness first hand the depravity of Hakkar and the Gurubashi.  Wrest the Paragons of Power that we seek from them; success will be rewarded!", sourceObjective = "Bring Al'tabim the All-Seeing a Primal Hakkari Sash. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.", progress = "The Paragons of Power... do you have them?  Only when we have them will we be able to make use of the latent power stored inside them.  It will be good to turn the tables on the minions of the Blood God...", completion = "Success!  These will go a long way to building up our power against the rise of Hakkar.  With your help, we've taken a significant step in ensuring that the Blood God will not destroy us all.\n\nYou've earned honor with the tribe today, {name}.  Take this - the confessor's bindings - as a symbol of our thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[85624] = { id = 85624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Confessor's Mantle", description = "The confessors of the Zandalar all wear a distinctive mantle, marking them as the preservers of the tribe.  These mantles are woven with powerful mojo that aids them in judging those who would threaten our tribe.  As a priest, you too must spend your time judging those worthy and not; such a mantle would definitely be a blessing to you.\n\nIn exchange for fighting Hakkar's minions in Zul'Gurub and bringing me the Paragons of Power I seek, I will give you a mantle worthy of our finest confessors.", sourceObjective = "Bring Al'tabim the All-Seeing a Primal Hakkari Aegis. You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.", progress = "Do you have the Paragons of Power from Zul'Gurub?", completion = "Well done, {name} - the minions of Hakkar have surely felt the retribution of the Zandalar today, thanks to you.  Your actions have given you a permanent place of reverence within the tribe.  With our blessing, please take this confessor's mantle as your own!", sourceObjectiveStatus = "unverified-source-field" }
quests[85625] = { id = 85625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kezan's Unstoppable Taint", progress = "Call forth your demons, {class}. Let them bask in the energy of Kezan's Taint. Command them on the field of battle! Decimate the enemy!\n\nYes... The time has come to apply the final enhancement to Kezan's Taint. Give me the talisman.", completion = "Flay the flesh from their corpses. Watch as the shadows consume the Hakkari. Draw power from their fear, {class}. Let Kezan's Taint augment this power..." }
quests[85626] = { id = 85626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Demoniac's Wraps", description = "Warlocks tread dangerous ground in dealing with demons, but our demoniacs take this one step further.  Through an ancient and arcane ritual, they allow a demon to enter their being.  Rather than let it possess them though, they enslave the demon from the inside, absorbing the power of the beast for their own command.  It is a feat few are ever able to master.\n\nFor you to learn of the power of the demoniac, I must have Paragons of Power from Zul'Gurub.  Go there and retrieve that which we seek.", sourceObjective = "Bring Al'tabim the All-Seeing a Primal Hakkari Stanchion. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.", progress = "Have you returned with the Paragons of Power?  By defeating the diabolic minions of the Hakkar, you will not only prove yourself to us, but also your willingness to learn the ways of the demoniac.", completion = "Well done... no doubt they were made to pay in excruciating ways before they gave up the Paragons of Power.  Take this - the demoniac's wraps.  Made from powerful mojo used in summoning the demoniac's prey, it is a powerful tool in your acquisition of power.", sourceObjectiveStatus = "unverified-source-field" }
quests[85627] = { id = 85627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Demoniac's Mantle", description = "The demoniac seeks to embody power outright, not just possess it.  More than one of our demoniacs has lost a fight with a demon; with our enemies threatening us - especially in Zul'Gurub - the power that a demoniac is able to unleash on our foes is worth the sacrifice.  Our survival depends on crushing those who would destroy us; the fall of the Gurubashi Empire taught us this.\n\nTravel to Zul'Gurub and gain the Paragons of Power we need.  Do this, and a valuable demoniac item shall be yours.", sourceObjective = "Bring Al'tabim the All-Seeing a Primal Hakkari Sash. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.", progress = "Retrieved the Paragons of Power from Zul'Gurub?  While we will take the latent power from these items and make them our own, we will give you your own reward of power should you be successful...", completion = "Well done, {name}.  The Paragons of Power from Zul'Gurub should act as a reminder of wasted power.  The Gurubashi were strong at their height, but they allowed themselves to be consumed by it.  A demoniac knows that the game they play is much similar, but the power unleashed is often the very thing needed for survival.\n\nUse this mantle as an honored ally of the Zandalar... it will serve you well.", sourceObjectiveStatus = "unverified-source-field" }
quests[85628] = { id = 85628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Demoniac's Robes", description = "The ultimate symbol of power amongst the tribe is the garb we wear in battle.  A demoniac's robes have fused fine runecloth and devastatingly powerful mojo into a single fabric.  The visage of the robe is said to instill fear into the minds of all who see it... especially the demons that the demoniac will eventually dominate.\n\nFrom Zul'Gurub, you must bring me a very specific set of the Paragons of Power.  It will be difficult... but your success will assure you of acquiring a robe for yourself.", sourceObjective = "Bring Al'tabim the All-Seeing a Primal Hakkari Kossack. You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.", progress = "The Paragons of Power... you have returned with them?  Only once we have them will we share the ultimate symbol of demoniac power with you, {name}.", completion = "Impressive - your victory in Zul'Gurub has assured us - nay, the world - that Hakkar will not prevail.  The time may come when you face the Blood God directly... and should this come to pass know that your reverence is assured amongst the Zandalar tribe.\n\nOh, and this simple robe should help out too I think.\n\n<Al'tabim winks knowingly at you.>", sourceObjectiveStatus = "unverified-source-field" }
quests[85629] = { id = 85629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Jewel of Kajaro", progress = "Give me the talisman, {name}. I must show you something.", completion = "<Al'tabim shatters the pebble with a powerful unseen force.>\n\nDo you see? The pebble is what we call a geode. Inside the pebble are powerful crystals that have been soaking in the latent energies from our world. By cutting the pebble in half, I have finally allowed its full potential to be realized. Use it to lay waste to our enemies." }
quests[85630] = { id = 85630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Illusionist's Wraps", description = "Mages in our tribe are known as illusionists.  They employ powerful mojo in their incantations, often befuddling and confusing the tribe's enemies!\n\n<Al'tabim laughs wickedly.>\n\nIt is quite the sight to see a powerful illusionist at work, bringing our enemies to their knees from their own madness!\n\nFor you to know the way of our illusionists, go to Zul'Gurub and bring back to me selected Paragons of Power.  For this, I will give you arm wraps our illusionists use to weave their spells.", sourceObjective = "Bring Al'tabim the All-SeeingPrimal Hakkari Bindings. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.", progress = "{name} - you've returned already?  Were you able to get the Paragons of Power I need?", completion = "Impressive... could you feel the mojo flowing through them?  The Paragons of Power were used as currency of sorts back when the Gurubashi Empire ruled these lands.  Now we Zandalar will use the latent mojo inside of them to fight the second rise of the Blood God Hakkar!\n\nYou've done well today - consider yourself to have a friend in the Zandalar.  For that, here are the illusionist's wraps I promised!", sourceObjectiveStatus = "unverified-source-field" }
quests[85631] = { id = 85631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Illusionist's Mantle", description = "Magic is a raw, primal force to be shaped by those strong enough to do it.  Mojo is our extension of this power; one such potent manipulation of it is in the form of illusion.  How can one truly hope to win against a foe that is not even really there?  We Zandalar know the power of this, and as such illusionists hold a honored place within the tribe.\n\nTake the needed Paragons of Power from Zul'Gurub - for this, honor from the tribe and a powerful mantle used by our best illusionists will be yours!", sourceObjective = "Bring Al'tabim the All-Seeing a Primal Hakkari Shawl. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.", progress = "How was your foray into Zul'Gurub?  Did you drive your enemies mad through the power of illusion?  Illusion or not, their deaths - and the Paragons of Power taken from them - will help thwart the rise of Hakkar.", completion = "Success!  You shall be honored in the tribe from here on!  Zul'Gurub has certainly tasted the might of the Zandalar today, thanks to you {name}.\n\nWith the tribe's blessing, take the Zandalar illusionist's mantle.  May it serve you well.", sourceObjectiveStatus = "unverified-source-field" }
quests[85632] = { id = 85632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Illusionist's Robes", description = "The tribe acknowledges station and power through what we wear.  Our vestments are made from the finest of materials, and interwoven with the mojo we use to make us powerful.  Illusionists are no exception; their robes are said to embody the essence of illusion in their look.  Legend states that their ancient robes never looked the same twice.\n\nI will give you an illusionist's robe, {name}... but earn your place of reverence among the tribe first!  Bring me the Paragons of Power from Zul'Gurub!", sourceObjective = "Bring Al'tabim the All-Seeing a Primal Hakkari Kossack. You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.", progress = "Have you returned with the Paragons of Power we need?  I know it will not be easy... but I have long predicted an outsider would come to aid us in our fight against Hakkar.  Let it be you, I say!", completion = "At last, someone worthy to wear the illusionist's robe!  Your success in Zul'Gurub has assured your reverences amongst the tribe for ages to come.  Wear it with pride, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[85633] = { id = 85633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zandalarian Shadow Mastery Talisman", progress = "It yearns to grow, {name}. The talisman has soaked in all that you have done. The thousands of troll corpses littering Zul'Gurub have fueled its power. Hand it to me and I shall make the final enhancement.", completion = "This is the last time we will speak under the auspices of Shera Ali'kh. You know all that you must. Take the talisman and continue in your slaying. Hakkar must never be allowed to leave Zul'Gurub." }
quests[85634] = { id = 85634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Madcap's Bracers", description = "The madcaps of Zandalar are similar to rogues, but above all else they embrace madness... chaos... the unpredictability of existence.  A terror to behold on the battlefield, they sowed the seeds of confusion and mayhem amongst our enemies in the savage times after the tribes splintered.  We would not be here today without them.\n\nBring to me the Paragons of Power from Zul'Gurub that I seek, and I will grant you the first of the madcap's prized armors.  Embrace the madness!", sourceObjective = "Bring Falthir the Sightless a Primal Hakkari Armsplint. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nFalthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.", progress = "Seek the madness from within Zul'Gurub and overshadow it with your own, {name}!  To do so means success, and success means reward!  Let not the Blood God reign supreme again!", completion = "Well done, {name}... your accomplishments in Zul'Gurub have earned you the right to call the Zandalar tribe as a friend.  I will see to the disposition of the Paragons; for your effort please accept this reward!", sourceObjectiveStatus = "unverified-source-field" }
quests[85635] = { id = 85635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Madcap's Mantle", description = "One of Zandalar's legendary madcaps was Khar'vaxal the Cracked.  Legend states that when facing the enemies of the tribe for the first time, Kar'xavan used his mantle specifically woven with \"the weave of madness\".  His form was shrouded not only by the mantle, but also with the blinding speed of his twin daggers.  Madcaps today cherish their mantle as a sign of their place in the tribe.\n\nBring to me the Paragons of Power I seek, and such a mantle will be yours to weave madness unto your own enemies.", sourceObjective = "Bring Falthir the Sightless a Primal Hakkari Girdle. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nFalthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.", progress = "You've returned - do you have the Paragons of Power I need?\n\nThe legend of Khar'vaxal the Cracked serves us today as a reminder that no foe - no matter how great a threat they may be - is impossible to overcome.  Chaos will bring everyone to their knees, that much is certain... and perhaps the most non-chaotic elements of chaos.", completion = "Victory is ours this day, thanks to the madness you have sowed upon our mutual enemies!  You are to be honored amongst the Zandalar, and there is no better way of showing gratitude for your deeds than by offering you the madcap's mantle!", sourceObjectiveStatus = "unverified-source-field" }
quests[85636] = { id = 85636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Madcap's Tunic", description = "My eyes failed me long ago, but I do not miss them.  Even in a tribe such as ours - where one's vestments convey station and purpose - the most potent of garb exudes power that simple eyes cannot see.  The prized tunic of the Zandalar madcap is no exception, exuding the raw power of chaos and madness that they are able to channel.\n\nThe Paragons of Power I need lie in Zul'Gurub; bring me what I seek, and I will reward you with your own legendary tunic... one befitting a weaver of madness.", sourceObjective = "Bring Falthir the Sightless a Primal Hakkari Aegis. You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nFalthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.", progress = "Welcome back to the Isle, {name}... have you returned triumphantly with the Paragons of Power in tow?", completion = "Impressive... you have accomplished today what few thought was possible.  Your reverence in the tribe is assured for a lifetime, {name}.  You have earned the right to don the madcap's tunic - do so with our blessing.", sourceObjectiveStatus = "unverified-source-field" }
quests[85637] = { id = 85637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maelstrom's Wrath", progress = "Molthor delivers word from King Rastakhan, {name}. The royal court is most impressed with your decimation of the Hakkari forces. I am to award you with the final weave in your talisman. Hand it to me.", completion = "Your journey has only just begun, young {class}. Perhaps one day you will visit the Maelstrom and glance into the heart of the world.\n\nI wish you power and fortitude!" }
quests[85638] = { id = 85638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Predator's Bracers", description = "In the dark times after the fall of the Gurubashi Empire, Zandalar predators used their prowess to provide sustenance for the tribe.  Hunters claim to be much like our tribe's predators - to seek the hunt is to embody the essence of the predator, yes.  Your hunt in Zul'Gurub, however, will show us how you truly rate amongst our finest predators.\n\nBring to me a sampling of the Paragons of Power from within Zul'Gurub.  Do so, and you'll take first steps in becoming the penultimate predator.", sourceObjective = "Bring the following Paragons of Power from Zul'Gurub to Falthir the Sightless: A Primal Hakkari Bindings. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nFalthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.", progress = "Hunt those in Zul'Gurub that would possess the Paragons of Power, {name}.  They are your prey; they possess that which we both must have.", completion = "Yes... I need no vision to sense the presence of the Paragons of Power.  Your success in Zul'Gurub has impressed many among the tribe.  We not only consider you to be a friend of the Zandalar, but also consider you worthy enough to possess the predator's bracers - powerful items, and a symbol of what it means to be a predator.  Well done, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[85639] = { id = 85639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Predator's Belt", description = "A predator knows how to stalk their prey, but a successful one knows how to strike at it once they have closed ranks.  You must master both to have any chance of success in Zul'Gurub... and any chance of being like the Zandalar predators.\n\nBring me choice parts of the Paragons of Power from within Zul'Gurub.  My reward will be the power that the trinkets yield, while yours will be the Zandalar predator's belt - equipment well worth the trade.", sourceObjective = "Bring the following Paragons of Power from Zul'Gurub to Falthir the Sightless: A Primal Hakkari Shawl. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nFalthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.", progress = "Strike at the insane minions of Hakkar in Zul'Gurub - they are the ones that hold the Paragons of Power, {name}.  Prove your success to them - and to the tribe - as an aspirant to the predator.", completion = "I sensed your arrival moments before, {name}, but none too easily.  What revealed yourself to me were the Paragons of Power you brought.  I can feel the power without needing to see the trinkets; their latent mojo - raw magic, if you will - will continue to fuel our efforts of vanquishing the diabolic schemes of the Blood God Hakkar.\n\nYou are to be commended - and rewarded - for your success.  You are honored amongst the tribe, and you are worthy to wear the predator's belt.", sourceObjectiveStatus = "unverified-source-field" }
quests[85640] = { id = 85640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Predator's Mantle", description = "We Zandalar prize what we wear as a symbol of accomplishment.  You don't need to be able to see what one wears to be able to sense what emanates from it - power transcends sight.  The garments of the Zandalar predator are like this, and most cherished by them is the mantle they wear.  It helps to obfuscate them from view... and to make their presence known when they wish it.\n\nThe Paragons of Power await your retrieval in Zul'Gurub.  Bring me what I seek, and the predator's mantle shall be yours.", sourceObjective = "Bring the following Paragons of Power from Zul'Gurub to Falthir the Sightless: A Primal Hakkari Aegis. You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nFalthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.", progress = "Have your strikes into Zul'Gurub yielded success, {name}?  Only when you've brought me what I seek - and proven yourself fully to the tribe - will you earn a mantle second to none amongst the Zandalar.", completion = "Success... you are to be revered amongst the tribe, {name}.  It was no small feat acquiring the Paragons of Power needed for the mantle, but you handled it in the fashion of the deadliest of our predators.  You've earned your place amongst them, and you've certainly earned the right to wear their mantle.", sourceObjectiveStatus = "unverified-source-field" }
quests[85643] = { id = 85643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lord of Blackrock", description = "Go to the Valley of Heroes and speak with Field Marshal Stonebridge.", sourceObjective = "Venture to the Valley of Heroes in Stormwind City and speak with Field Marshal Stonebridge.", completion = "<Field Marshal Stonebridge bows.>\n\nChoose your reward, let the celebration begin!", sourceObjectiveStatus = "unverified-source-field" }
quests[85644] = { id = 85644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lord of Blackrock", description = "Seek out High Overlord Saurfang in the Valley of Strength.", sourceObjective = "Speak with High Overlord Saurfang in Orgrimmar. He stands waiting for you in the Valley of Strength.", completion = "Choose your reward so that I may mount the head of the beast for all to see.", sourceObjectiveStatus = "unverified-source-field" }
quests[85658] = { id = 85658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For All To See", description = "Overlord Runthak awaits your arrival in the Valley of Strength.\n\n<Thrall salutes you.>\n\nDo not keep your public waiting, hero.", sourceObjective = "Seek out Overlord Runthak in the Valley of Strength.", completion = "Choose your reward and let the celebration of your glorious victory begin.", sourceObjectiveStatus = "unverified-source-field" }
quests[85659] = { id = 85659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Celebrating Good Times", description = "Seek out Major Mattingly in the Valley of Heroes, {name}. He will be expecting you...", sourceObjective = "Seek out Major Mattingly in the Valley of Heroes.", completion = "Few are graced with such ceremony, {name}. Please, choose your reward so that we may begin the celebration.", sourceObjectiveStatus = "unverified-source-field" }
quests[85660] = { id = 85660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of Hakkar", description = "The Heart of Hakkar burns from within.  Although the Soulflayer is defeated, the kernel of his power yet remains in this cursed organ.", sourceObjective = "Bring the Heart of Hakkar to Molthor on Yojamba Isle.", completion = "Ah, the Heart of Hakkar.  So the Soulflayer has been slain!  Our world is saved!\n\n{name}, your service to us cannot be overstated.  You truly are a hero of this realm!", sourceObjectiveStatus = "unverified-source-field" }
quests[85699] = { id = 85699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snakestone of the Shadow Huntress", description = "Don't let her beauty fool you, {class}. The shadow huntress, Vosh'gajin is deadly and deranged.\n\n<Kilram points to the scar on his face.>\n\nAye, she gave me that - a love tap, she called it.\n\nThe time for vengeance has finally come.\n\nYou can find Vosh'gajin in Blackrock Spire. Slay her and return to me with her snakestone. Do this and I will teach you the ways of the axesmith.", sourceObjective = "Travel to Blackrock Spire and slay Shadow Hunter Vosh'gajin. Recover Vosh'gajin's Snakestone and return to Kilram.", progress = "Legend states that one use of Vosh'gajin's snakestone will keep an axe razor sharp for a 1000 years!", completion = "So you are certain this is what you want? To become an axesmith? Remember, the doors to becoming a swordsmith and hammersmith will close forever.", sourceObjectiveStatus = "unverified-source-field" }
quests[85700] = { id = 85700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corruption", description = "If I am short with you, it is for a reason. The plans for the creation of the great blade, Corruption, have been stolen by the Black Guard: Elite skeletal units of Baron Rivendare.\n\nYes, Baron Rivendare of Stratholme.\n\nThe Black Guard swordsmith now guards those plans with his... undeath.\n\nSlay him and return proof of this deed and I shall train you in the ways of the swordsmith.", sourceObjective = "Find the Black Guard Swordsmith in Stratholme and destroy him. Recover the Insignia of the Black Guard and return to Seril Scourgebane.", progress = "Have you forgotten what it is that you were tasked with, {name}?", completion = "So you are certain that this is what you want? To become a swordsmith? Remember, the doors to becoming a hammersmith and axesmith will close forever.", sourceObjectiveStatus = "unverified-source-field" }
quests[85701] = { id = 85701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonscale Leatherworking", description = "Dragonscale leatherworking isn't easy, but it's extremely rewarding.  I'll teach you how to make this fine mail armor, but only if you agree to certain conditions.\n\nBy choosing this path, you agree never to learn elemental or tribal leatherworking; there is only room for one of the three at the apex of the craft.  Furthermore, I'll need some samples of your best work involving scorpid armor.  Finally, I'll need proof of your ability to acquire the staple of the trade: scales of the dragonkin.", sourceObjective = "Bring 2 Tough Scorpid Breastplates, 2 Tough Scorpid Gloves, and 10 Worn Dragonscales to Peter Galen in Azshara.\n\nCompleting this quest will give you access to the Dragonscale Leatherworking arts.\n\nThe completion of this quest will prevent you from learning Elemental Leatherworking and Tribal Leatherworking; be sure this is the path you wish to follow before doing so.", progress = "If you're ready to commit to a permanent decision by becoming a dragonscale leatherworker, then I'm ready to take you on as a student.  Just bring to me the things I asked for, and we'll begin your education.", completion = "I'll hand it to you - it takes a strong will to make a permanent decision like you've just done.  I assure you, dragonscale leatherworking will prove to be a profitable and rewarding path for you to follow.\n\nTo train in the art for the future, simply speak to me and I will make available any knowledge that you have yet to commit as yours.", sourceObjectiveStatus = "unverified-source-field" }
quests[85702] = { id = 85702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonscale Leatherworking", description = "Dragonscale leatherworking isn't easy, but it's extremely rewarding.  I'll teach you how to make this fine mail armor, but only if you agree to certain conditions.\n\nBy choosing this path, you agree never to learn elemental or tribal leatherworking; there is only room for one of the three at the apex of the craft.  Furthermore, I'll need some samples of your best work involving scorpid armor.  Finally, I'll need proof of your ability to acquire the staple of the trade: scales of the dragonkin.", sourceObjective = "Bring 2 Tough Scorpid Breastplates, 2 Tough Scorpid Gloves, and 10 Worn Dragonscales to Thorkaf Dragoneye in the Badlands.\n\nCompleting this quest will give you access to the Dragonscale Leatherworking arts.\n\nThe completion of this quest will prevent you from learning Elemental Leatherworking and Tribal Leatherworking; be sure this is the path you wish to follow before doing so.", progress = "If you're ready to commit to a permanent decision by becoming a dragonscale leatherworker, then I'm ready to take you on as a student.  Just bring to me the things I asked for, and we'll begin your education.", completion = "I'll hand it to you - it takes a strong will to make a permanent decision like you've just done.  I assure you, dragonscale leatherworking will prove to be a profitable and rewarding path for you to follow.\n\nTo train in the art for the future, simply speak to me and I will make available any knowledge that you have yet to commit as yours.", sourceObjectiveStatus = "unverified-source-field" }
quests[85703] = { id = 85703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Leatherworking", description = "Elemental leatherworking is what I know, and if you're willing to open your mind to the greater powers of substance, I will share with you all there is to learn.\n\nKnow this, {class}: by choosing this path you agree never to learn dragonscale or tribal leatherworking; there is only room for practice of one of the three arts.  Furthermore, I'll need adequate proof that you are in tune with the elements of nature; to that end, bring me the purest essences of fire, water, earth, and wind.", sourceObjective = "Bring 2 Heart of Fire, 2 Globe of Water, 2 Core of Earth, and 2 Breath of Wind to Sarah Tanner in Searing Gorge.\n\nCompleting this quest will give you access to the Elemental Leatherworking arts.\n\nThe completion of this quest will prevent you from learning Dragonscale Leatherworking and Tribal Leatherworking; be sure this is the path you wish to follow before doing so.", progress = "Making this kind of leather-based armor requires patience and dedication.  Once you have cast your lot with the elements, there is no turning your back on them.  Bring me proof of your worthiness, and we'll get started.", completion = "You've cast your lot, and the elements accept you.  Once I have finished my tutelage, you shall command the will to craft the finest of leather garbs.\n\nTo train in the art for the future, simply speak to me and I will make available any knowledge that you have yet to commit as yours.", sourceObjectiveStatus = "unverified-source-field" }
quests[85704] = { id = 85704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Leatherworking", description = "Elemental leatherworking is what I know, and if you're willing to open your mind to the greater powers of substance, I will share with you all there is to learn.\n\nKnow this, {class}: by choosing this path you agree never to learn dragonscale or tribal leatherworking; there is only room for practice of one of the three arts.  Furthermore, I'll need adequate proof that you are in tune with the elements of nature; to that end, bring me the purest essences of fire, water, earth, and wind.", sourceObjective = "Bring 2 Heart of Fire, 2 Globe of Water, 2 Core of Earth, and 2 Breath of Wind to Brumn Winterhoof in the Arathi Mountains.\n\nCompleting this quest will give you access to the Elemental Leatherworking arts.\n\nThe completion of this quest will prevent you from learning Dragonscale Leatherworking and Tribal Leatherworking; be sure this is the path you wish to follow before doing so.", progress = "Making this kind of leather-based armor requires patience and dedication.  Once you have cast your lot with the elements, there is no turning your back on them.  Bring me proof of your worthiness, and we'll get started.", completion = "You've cast your lot, and the elements accept you.  Once I have finished my tutelage, you shall command the will to craft the finest of leather garbs.\n\nTo train in the art for the future, simply speak to me and I will make available any knowledge that you have yet to commit as yours.", sourceObjectiveStatus = "unverified-source-field" }
quests[85705] = { id = 85705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tribal Leatherworking", description = "To learn tribal leatherworking demands an understanding of how primal nature truly is; I know that you have already mastered the art of making wild leather armor, and I am willing to complete your training.\n\nKnow this, {class}: by choosing this path you agree never to learn dragonscale or elemental leatherworking; there is only room for practice of one of the three arts.  Furthermore, bring to me the finest samples of your wild leather armor.  From there, we will begin your mastery.", sourceObjective = "Bring a Wild Leather Vest and a Wild Leather Helmet to Caryssia Moonhunter in Feralas.\n\nCompleting this quest will give you access to the Tribal Leatherworking arts.\n\nThe completion of this quest will prevent you from learning Dragonscale Leatherworking and Elemental Leatherworking; be sure this is the path you wish to follow before doing so.", progress = "Nature is a force that must be appeased before you hope to learn how to bend its will into your leather garments.  Bring me your offering to this force, and I will make sure you are heard.", completion = "You've given your finest offerings, and nature will soon permit you to bend her to your will.  Once I have finished my tutelage, your work will be a force of nature unto itself.\n\nTo train in the art for the future, simply speak to me and I will make available any knowledge that you have yet to commit as yours.", sourceObjectiveStatus = "unverified-source-field" }
quests[85706] = { id = 85706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tribal Leatherworking", description = "To learn tribal leatherworking demands an understanding of how primal nature truly is; I know that you have already mastered the art of making wild leather armor, and I am willing to complete your training.\n\nKnow this, {class}: by choosing this path you agree never to learn dragonscale or elemental leatherworking; there is only room for practice of one of the three arts.  Furthermore, bring to me the finest samples of your wild leather armor.  From there, we will begin your mastery.", sourceObjective = "Bring a Wild Leather Vest and a Wild Leather Helmet to Se'Jib in Stranglethorn Vale.\n\nCompleting this quest will give you access to the Tribal Leatherworking arts.\n\nThe completion of this quest will prevent you from learning Dragonscale Leatherworking and Elemental Leatherworking; be sure this is the path you wish to follow before doing so.", progress = "Nature is a force that must be appeased before you hope to learn how to bend its will into your leather garments.  Bring me your offering to this force, and I will make sure you are heard.", completion = "You've given your finest offerings, and nature will soon permit you to bend her to your will.  Once I have finished my tutelage, your work will be a force of nature unto itself.\n\nTo train in the art for the future, simply speak to me and I will make available any knowledge that you have yet to commit as yours.", sourceObjectiveStatus = "unverified-source-field" }
quests[85712] = { id = 85712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Art of the Armorsmith", description = "Satisfaction. It is what I draw from the hammer and the anvil. To see a proud Horde warrior protected under my steel reminds me of what it is to be alive. It is an addiction that I dare never give up, {name}.\n\nI can not grant you this satisfaction, merely set you upon the path. As with all of life's endeavors, the path of the armorsmith is a journey.\n\nIf you wish to be one of the select few, you need only to ask and I shall train, but, a task you must first complete.", sourceObjective = "To become an armorsmith, you must make the following items and return them to Okothos: 4 Ornate Mithril Helms, 2 Ornate Mithril Boots, 1 Ornate Mithril Breastplate.", progress = "I will pound the steel until the breath itself has been taken from me.", completion = "This is the final step before you begin your new career as an armorsmith, {name}. Should you choose to back out, now would be your last chance. Otherwise, prepare yourself for a lifetime of glory.", sourceObjectiveStatus = "unverified-source-field" }
quests[85713] = { id = 85713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Art of the Armorsmith", description = "So ye made the smart decision.\n\nThere ain't no love lost betwixt me an old Ironus here. That good for nothing toy maker knows who the true craftsmen round here be.\n\nThe truly great wars are won with a good defense. When it be go time, no offense is gonna be helping ye out.\n\nRight, so let's get to work. All ye need to do is show me that ye've got some raw talent. After that, I'll yank whatever impurities be left in ye and mold ye into an armorsmith. Ye do know how to make ornate mithril, don't ye?", sourceObjective = "To become an Armorsmith, you must make the following items and return them to Grumnus: 4 Ornate Mithril Helms, 2 Ornate Mithril Boots, 1 Ornate Mithril Breastplate.", progress = "Ah, ain't nothing like a good forge tan. Ye can tell who's got the really good tans by their apron lines.", completion = "This be it, {name}. After this, there ain't no way to turn back. It's not too late to become a toy maker, er, weaponsmith.\n\nI trust ye'll make the right decision.", sourceObjectiveStatus = "unverified-source-field" }
quests[85772] = { id = 85772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Distress", description = "Listen, {name}. The corruption I spoke of before goes beyond Baron Aquanis. I've been sensing a certain unease within the elemental world for some time. I fear something is gravely wrong, and the corruption of Baron Aquanis only furthers my suspicions.\n\nFind more of those elementals who are suffering: here in Ashenvale, and in the nearby Stonetalon Mountains. Bring me motes of their essence. Perhaps I can analyze them, and begin to understand the nature of their rage.", sourceObjective = "Collect motes of elemental rage, and bring them to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.", completion = "I recently spoke with a group of heroes who traveled into Blackfathom Deeps and battled the evil dwelling within. They brought me the heart of the mighty elemental Baron Aquanis, and I have been puzzling over what has corrupted him and the other elementals.\n\nCould you assist in my investigation?", sourceObjectiveStatus = "unverified-source-field" }
quests[85798] = { id = 85798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arms for the Field", description = "The Ironforge Brigade has been a worthy ally in our fight in Silithus.  Unfortunately, many of their supplies were lost on their way here.  Procure a batch of weapons and deliver them to Janela Stouthammer near Hive'Zora.", sourceObjective = "Bring 2 Moonsteel Broadswords to Janela Stouthammer at the Ironforge Brigade Outpost outside of Hive'Zora. You must also bring Logistics Task Briefing VI in order to complete this quest.", progress = "You have something for me, {name}?", completion = "Oh, excellent!  I won't have to hear complaints about dull blades anymore.  Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[85882] = { id = 85882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "End of the Dark Horde", description = "The deed is done. Dal'rend Blackhand, Warchief of the Dark Horde, lies dead at your feet. Take his head and present it to Master Shaw.", sourceObjective = "Take the Head of Rend Blackhand to Master Mathias Shaw in Stormwind.", completion = "Well done, champion.  The Warchief of the Dark Horde is dead, ending an era of terror in our lands. Let all of Stormwind know of your victory!", sourceObjectiveStatus = "unverified-source-field" }
quests[85883] = { id = 85883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For The Horde!", description = "Rend dares make such grand claims because of the protection he is afforded by the black flight.\n\nYou, {name}, will find a way to pass through the Halls of Ascension. You will then find 'Warchief' Rend Blackhand and you will destroy him - FOR THE HORDE!\n\n<Thrall slams a fist down upon his throne.>\n\nThe next time you return to my chambers, you will hold his head high in triumph and then you shall present it to your Warchief. Do this and be honored as a hero of the Horde.", sourceObjective = "Travel to Blackrock Spire and slay Warchief Rend Blackhand. Take his head and return to Orgrimmar.", completion = "You have dealt a crippling blow to the forces of Blackrock, {name}. With their Warchief slain, the Blackrock legion is once again thrown into the maw of chaos.\n\nIn honor of your heroics, the people of Kalimdor shall be rewarded!", sourceObjectiveStatus = "unverified-source-field" }
quests[85963] = { id = 85963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Commendation Signet", progress = "For those adventurers who have but a single commendation signet, I'll exchange it for a small amount of recognition with the Argent Dawn.\n\nPlease bear in mind that it is better to hand over a stack of ten signets at once; your efforts will receive greater recognition in doing so.  We offer a single signet exchange as a service for those who don't have enough for a full stack of ten.\n\nWith that being said, I stand ready to assist you if you still wish to hand in a single signet.", completion = "Very well - your deeds have been entered into the records, and you are duly recognized for your efforts.  Keep up the good work, {class}.\n\nIf you have any more signets to hand in, then I am able to assist you further in that regard." }
quests[85964] = { id = 85964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ten Commendation Signets", progress = "I accept commendation signets from adventurers who have received them in the line of duty.  For each set of ten that you hand to me, I'll make sure that you receive a significant acknowledgement of your deeds with the Argent Dawn.  I also accept single tokens, but at a much reduced rate of recognition.  We are much more interested in greater feats of duty, though no feat will be ignored.\n\nWith that said, I'll gladly take your signets if you are ready to hand in a set.", completion = "Excellent!  It is no small sacrifice that you've made to earn these signets, and you will be acknowledged for your service appropriately.  It's adventurers like you, {name}, that truly make a difference.\n\nLet me know if you have additional signets to hand in; I'll gladly help you out with whatever ones you need exchanged." }
quests[85965] = { id = 85965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Commendation Signet", progress = "For those adventurers who have but a single commendation signet, I'll exchange it for a small amount of recognition with the Argent Dawn.\n\nPlease bear in mind that it is better to hand over a stack of ten signets at once; your efforts will receive greater recognition in doing so.  We offer a single signet exchange as a service for those who don't have enough for a full stack of ten.\n\nWith that being said, I stand ready to assist you if you still wish to hand in a single signet.", completion = "Very well - your deeds have been entered into the records, and you are duly recognized for your efforts.  Keep up the good work, {class}.\n\nIf you have any more signets to hand in, then I am able to assist you further in that regard." }
