quests[85971] = { id = 85971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Commendation Signet", progress = "For those adventurers who have but a single commendation signet, I will exchange it for a small amount of recognition with my forces, the Hydraxian Waterlords.\n\nPlease bear in mind that it is better to hand over a stack of ten signets at once; your efforts will receive greater recognition in doing so.  I offer a single signet exchange as a service for those who do not have enough for a full stack of ten.\n\nWith that being said, I will accept it if you still wish to hand in a single signet.", completion = "Very well - your deeds have been recognized.  Keep up the good work, {class}.\n\nIf you have any more signets to hand in, I will accept them." }
quests[85972] = { id = 85972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Commendation Signet", progress = "For those adventurers who have but a single commendation signet, I will exchange it for a small amount of recognition with my forces, the Hydraxian Waterlords.\n\nPlease bear in mind that it is better to hand over a stack of ten signets at once; your efforts will receive greater recognition in doing so.  I offer a single signet exchange as a service for those who do not have enough for a full stack of ten.\n\nWith that being said, I will accept it if you still wish to hand in a single signet.", completion = "Very well - your deeds have been recognized.  Keep up the good work, {class}.\n\nIf you have any more signets to hand in, I will accept them." }
quests[85973] = { id = 85973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ten Commendation Signets", sourceObjective = "I accept commendation signets from adventurers who have received them in the line of duty.  For each set of ten that you hand to me, you will receive significant recognition from my forces, the Hydraxian Waterlords.  I also accept single tokens, but at a much reduced rate of recognition.  I am much more interested in greater feats of duty, though no feat will be ignored.\n\nWith that said, I will accept your signets if you are ready to hand in a set.", completion = "Excellent!  It is no small sacrifice that you have made to earn these signets, and you will be acknowledged for your service appropriately.  It is adventurers like you, {name}, that truly make a difference.\n\nLet me know if you have additional signets to hand in; I will gladly accept them.", sourceObjectiveStatus = "unverified-source-field" }
quests[85974] = { id = 85974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ten Commendation Signets", sourceObjective = "I accept commendation signets from adventurers who have received them in the line of duty.  For each set of ten that you hand to me, you will receive significant recognition from my forces, the Hydraxian Waterlords.  I also accept single tokens, but at a much reduced rate of recognition.  I am much more interested in greater feats of duty, though no feat will be ignored.\n\nWith that said, I will accept your signets if you are ready to hand in a set.", completion = "Excellent!  It is no small sacrifice that you have made to earn these signets, and you will be acknowledged for your service appropriately.  It is adventurers like you, {name}, that truly make a difference.\n\nLet me know if you have additional signets to hand in; I will gladly accept them.", sourceObjectiveStatus = "unverified-source-field" }
quests[85975] = { id = 85975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Commendation Signet", progress = "For those adventurers who have but a single commendation signet, I'll exchange it for a small amount of recognition with the Thorium Brotherhood.\n\nPlease bear in mind that it is better to hand over a stack of ten signets at once; your efforts will receive greater recognition in doing so.  We offer a single signet exchange as a service for those who don't have enough for a full stack of ten.\n\nWith that being said, I stand ready to assist you if you still wish to hand in a single signet.", completion = "Very well - your deeds have been entered into the records, and you are duly recognized for your efforts.  Keep up the good work, {class}.\n\nIf you have any more signets to hand in, then I am able to assist you further in that regard." }
quests[85976] = { id = 85976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ten Commendation Signets", progress = "I accept commendation signets from adventurers who have received them in the line of duty.  For each set of ten that you hand to me, I'll make sure that you receive a significant acknowledgement of your deeds with the Thorium Brotherhood.  I also accept single tokens, but at a much reduced rate of recognition.  We are much more interested in greater feats of duty, though no feat will be ignored.\n\nWith that said, I'll gladly take your signets if you are ready to hand in a set.", completion = "Excellent!  It is no small sacrifice that you've made to earn these signets, and you will be acknowledged for your service appropriately.  It's adventurers like you, {name}, that truly make a difference.\n\nLet me know if you have additional signets to hand in; I'll gladly help you out with whatever ones you need exchanged." }
quests[85977] = { id = 85977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Commendation Signet" }
quests[85978] = { id = 85978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ten Commendation Signets", progress = "I accept commendation signets from adventurers who have received them in the line of duty.  For each set of ten that you hand to me, I'll make sure that you receive a significant acknowledgement of your deeds with the Thorium Brotherhood.  I also accept single tokens, but at a much reduced rate of recognition.  We are much more interested in greater feats of duty, though no feat will be ignored.\n\nWith that said, I'll gladly take your signets if you are ready to hand in a set.", completion = "Excellent!  It is no small sacrifice that you've made to earn these signets, and you will be acknowledged for your service appropriately.  It's adventurers like you, {name}, that truly make a difference.\n\nLet me know if you have additional signets to hand in; I'll gladly help you out with whatever ones you need exchanged." }
quests[85979] = { id = 85979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Commendation Signet", progress = "For those adventurers who have but a single commendation signet, I'll exchange it for a little bit of recognition with the Steamweedle Cartel.\n\nPlease bear in mind that it is better to hand over a stack of ten signets at once; your efforts will receive greater recognition in doing so.  We offer a single signet exchange as a service for those who don't have enough for a full stack of ten.\n\nWith that being said, I stand ready to swin... er, help you if you still wish to hand in a single signet.", completion = "Very well - your deeds have been entered into the ledgers, and you are duly recognized for your efforts.  Keep up the good work, {class}.\n\nIf you have any more signets to hand in, I can trade with you further." }
quests[85980] = { id = 85980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Commendation Signet", progress = "For those adventurers who have but a single commendation signet, I'll exchange it for a little bit of recognition with the Steamweedle Cartel.\n\nPlease bear in mind that it is better to hand over a stack of ten signets at once; your efforts will receive greater recognition in doing so.  We offer a single signet exchange as a service for those who don't have enough for a full stack of ten.\n\nWith that being said, I stand ready to swin... er, help you if you still wish to hand in a single signet.", completion = "Very well - your deeds have been entered into the ledgers, and you are duly recognized for your efforts.  Keep up the good work, {class}.\n\nIf you have any more signets to hand in, I can trade with you further." }
quests[85981] = { id = 85981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ten Commendation Signets", progress = "I accept commendation signets from adventurers who have received them in the line of duty.  For each set of ten that you hand to me, I'll make sure that you receive a significant acknowledgement of your deeds with the Steamweedle Cartel.  I also accept single tokens, but at a steep discount in recognition.  We are much more interested in greater feats of duty, though no feat will be ignored.\n\nWith that said, I'll gladly exchange your signets if you are ready to hand in a set.", completion = "Excellent!  It is no small sacrifice that you've made to earn these signets, and you will be acknowledged for your service appropriately.  It's adventurers like you, {name}, that truly make a difference.\n\nLet me know if you have additional signets to hand in; I'll happily cash them in for you." }
quests[85982] = { id = 85982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ten Commendation Signets", progress = "I accept commendation signets from adventurers who have received them in the line of duty.  For each set of ten that you hand to me, I'll make sure that you receive a significant acknowledgement of your deeds with the Steamweedle Cartel.  I also accept single tokens, but at a steep discount in recognition.  We are much more interested in greater feats of duty, though no feat will be ignored.\n\nWith that said, I'll gladly exchange your signets if you are ready to hand in a set.", completion = "Excellent!  It is no small sacrifice that you've made to earn these signets, and you will be acknowledged for your service appropriately.  It's adventurers like you, {name}, that truly make a difference.\n\nLet me know if you have additional signets to hand in; I'll happily cash them in for you." }
quests[85983] = { id = 85983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Commendation Signet", progress = "For those adventurers who have but a single commendation signet, I will exchange it for a minor recognition with the Zandalar Tribe.\n\nBear in mind it is better to hand over a stack of ten signets at once; your efforts will receive the greater recognition in doing so.  We also offer a single signet exchange as a boon for those who do not have enough for a full stack of ten.\n\nEven so, I stand ready to assist you if you still wish to hand in the single signet.", completion = "Very well - your deeds have been recognized by the Zandalar.  Keep up the good work, {class}.\n\nIf you have more of the signets to hand in, then I will assist you further." }
quests[85984] = { id = 85984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Commendation Signet", progress = "For those adventurers who have but a single commendation signet, I will exchange it for a minor recognition with the Zandalar Tribe.\n\nBear in mind it is better to hand over a stack of ten signets at once; your efforts will receive the greater recognition in doing so.  We also offer a single signet exchange as a boon for those who do not have enough for a full stack of ten.\n\nEven so, I stand ready to assist you if you still wish to hand in the single signet.", completion = "Very well - your deeds have been recognized by the Zandalar.  Keep up the good work, {class}.\n\nIf you have more of the signets to hand in, then I will assist you further." }
quests[85985] = { id = 85985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ten Commendation Signets", progress = "I accept commendation signets from adventurers who have received them in the line of duty.  For each set of ten that you hand to me, I will make sure that you receive a great boon recognition with the Zandalar Tribe.  I also accept single tokens, but with a much smaller boon.  We are much more interested in greater feats of duty, though no feat will be ignored.\n\nWith that said, I'll gladly take your signets if you are ready to hand in a set.", completion = "Excellent!  You have sacrificed to earn these signets, and you will receive appropriate boons.  Adventurers like you, {name}, truly make a difference.\n\nCome to me if you have additional signets to hand in; I will gladly assist you with the exchange." }
quests[85986] = { id = 85986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ten Commendation Signets", progress = "I accept commendation signets from adventurers who have received them in the line of duty.  For each set of ten that you hand to me, I will make sure that you receive a great boon recognition with the Zandalar Tribe.  I also accept single tokens, but with a much smaller boon.  We are much more interested in greater feats of duty, though no feat will be ignored.\n\nWith that said, I'll gladly take your signets if you are ready to hand in a set.", completion = "Excellent!  You have sacrificed to earn these signets, and you will receive appropriate boons.  Adventurers like you, {name}, truly make a difference.\n\nCome to me if you have additional signets to hand in; I will gladly assist you with the exchange." }
quests[85987] = { id = 85987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Commendation Signet", progress = "For those outsiders who come to me with a single commendation signet, I will exchange it for a small amount of favor with the Timbermaw.\n\nBear in mind that I am more impressed by a stack of ten signets at once; your efforts will receive greater favor from doing so.  I offer a single signet exchange merely as a convenience to those who don't have a full stack of ten.\n\nHowever, I stand ready to assist you if you still wish to give me a single signet.", completion = "Well done! The Timbermaw recognize for your efforts.  Keep up the good work, {class}.\n\nIf you have any more signets to hand in, I can help you further." }
quests[85988] = { id = 85988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Commendation Signet", progress = "For those outsiders who come to me with a single commendation signet, I will exchange it for a small amount of favor with the Timbermaw.\n\nBear in mind that I am more impressed by a stack of ten signets at once; your efforts will receive greater favor from doing so.  I offer a single signet exchange merely as a convenience to those who don't have a full stack of ten.\n\nHowever, I stand ready to assist you if you still wish to give me a single signet.", completion = "Well done! The Timbermaw recognize for your efforts.  Keep up the good work, {class}.\n\nIf you have any more signets to hand in, I can help you further." }
quests[86160] = { id = 86160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ten Commendation Signets", sourceObjective = "I accept commendation signets from outsiders who have received them in the line of duty.  For each set of ten that you hand to me, you will receive significant favor with the Timbermaw.  I also accept single tokens, but for much less favor.  I am much more interested in greater feats of service, though no feat will be ignored.\n\nI'll gladly exchange your signets if you are ready to hand in a set.", completion = "Excellent!  You have sacrificed to earn these signets, and and in doing so earned our favor.  Outsiders like you, {name}, can truly make a difference.\n\nReturn to me if you have additional signets to hand in; I will exchange them for additional favor.", sourceObjectiveStatus = "unverified-source-field" }
quests[86161] = { id = 86161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ten Commendation Signets", sourceObjective = "I accept commendation signets from outsiders who have received them in the line of duty.  For each set of ten that you hand to me, you will receive significant favor with the Timbermaw.  I also accept single tokens, but for much less favor.  I am much more interested in greater feats of service, though no feat will be ignored.\n\nI'll gladly exchange your signets if you are ready to hand in a set.", completion = "Excellent!  You have sacrificed to earn these signets, and and in doing so earned our favor.  Outsiders like you, {name}, can truly make a difference.\n\nReturn to me if you have additional signets to hand in; I will exchange them for additional favor.", sourceObjectiveStatus = "unverified-source-field" }
quests[86326] = { id = 86326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desert Power", description = "The deep and dark tunnels to ancient places of the world are ill suited for your travel.", sourceObjective = "Speak to Selestrasza to claim your Qiraji Resonating Crystal.", completion = "Your might has not gone unnoticed mortal. Let this tamed silithid hasten your travels into the ancient empire of the Qiraji.", sourceObjectiveStatus = "unverified-source-field" }
quests[86442] = { id = 86442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nefarius's Corruption", description = "Champion, is it you? A thousand years it has been since I was entrusted the shard and it is at my darkest hour that one should rise to relieve me of it... But what would tragedy be without cruelty?\n\n<Vaelastrasz coughs weakly.>\n\nNe... Nefarius now holds the scepter shard.\n\nTime is of the essence. Nefarius plans to destroy the shard. You must hurry!", sourceObjective = "Slay Nefarian and recover the Red Scepter Shard. Return the Red Scepter Shard to Anachronos at the Caverns of Time in Tanaris. You have 5 hours to complete this task.", progress = "Another of our heroes lost to the spawn of Deathwing. We will be cursed with this suffering forever...", completion = "Vaelastrasz's soul is at ease, champion. The Aspects all watch your progress with great interest. Know that you have powerful allies.\n\nI was commanded to grant you something to aid you in this struggle. Use it well...", sourceObjectiveStatus = "unverified-source-field" }
quests[86443] = { id = 86443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nightmare Manifests", description = "We must use restraint against Eranikus. We are to redeem him not destroy him.\n\nTyrande is already en route to assist us in this task. We must weather the dragon's blows and save Nighthaven from certain destruction.\n\nBe on guard! You and your allies are our only hope.", sourceObjective = "Defend Nighthaven from Eranikus. Do not let Keeper Remulos perish. Do not slay Eranikus. Defend yourself. Await Tyrande.", completion = "He is redeemed, {name}. He now returns to the Dream to right what he alone has done wrong. Eranikus will be a powerful ally to Malfurion and my father.\n\nThese armaments are for you, {name}; given to me by Ysera herself. You would do well to make use of them in your battles against the Qiraji.", sourceObjectiveStatus = "unverified-source-field" }
quests[86444] = { id = 86444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Only Prescription", description = "I should have known. My arch-enemy, Doctor Weavil, up to his old tricks! And now, thanks to your failure in Winterspring, Doctor Weavil has destroyed my book! How are you going to save the world now, hero?\n\nThe note I received stated that the only known copy of \"Draconic for Dummies: Volume II\" was ripped into 8 parts and scattered to the wind! If you somehow manage to find those missing chapters, use this magical binding to put them back together and return to me.", sourceObjective = "Recover the 8 lost chapters of Draconic for Dummies and combine them with the Magical Book Binding and return the completed book of Draconic for Dummies: Volume II to Narain Soothfancy in Tanaris.", progress = "I put my pants on just like you - one leg at a time. Except when my pants are on, I make arcanite buoys. Arcanite buoys, baby!", completion = "Fantastic! I can't believe you went through the hassle! Are you some kind of machine? If it were me, I would have probably just let the world implode.\n\nI tip my turban to you, sir. And no good deed should go unrewarded.", sourceObjectiveStatus = "unverified-source-field" }
quests[86445] = { id = 86445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wrath of Neptulon", description = "Did I mention the bad news yet? Its name is Maws: 100 feet of death and destruction. I guess I may have forgotten that little tidbit.\n\nAccording to my superior psycho-psionic clairvoyance, you'll find that the best spot to cast this buoy is off the coast of Azshara, in the Bay of Storms.\n\nLook for a swirling maelstrom, most likely cluttered with wreckage.\n\nBy the by, I hope you have friends.\n\nNow if you somehow miraculously succeed, take the scepter shard to Anachronos.", sourceObjective = "Use the Arcanite Buoy at the Swirling Maelstrom at the Bay of Storms in Azshara.", progress = "Time is running out, champion.", completion = "Well done, {name}. I will be able to reform the Scepter of the Shifting Sands soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[86449] = { id = 86449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure of the Timeless One", sourceObjective = "Greetings, champion. I am Jonathan, keeper of the sacred gong and eternal watcher of the Bronze Flight.\n\nI have been empowered by the Timeless One himself to grant you an item of your choosing from his timeless treasure trove. May it aid you in your battles against C'Thun.", sourceObjectiveStatus = "unverified-source-field" }
quests[86670] = { id = 86670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Savior of Kalimdor", description = "To the Caverns of Time you go, <Lord/Lady> {name}. Anachronos awaits your return. Give him the eye of C'Thun as he will undoubtedly wish to place it in his master's collection.", sourceObjective = "Take the Eye of C'Thun to Anachronos at the Caverns of Time.", progress = "Lord {name}! It is over...", completion = "The Master has left these for you, champion. From the timeless cache: A collection of artifacts spanning thousands of years - the choice is yours.", sourceObjectiveStatus = "unverified-source-field" }
quests[86671] = { id = 86671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperial Qiraji Regalia", description = "Arygos theorizes that the element which is born of conflicts between the Old Gods and their minions is also extremely deadly to them under the right conditions. I speak of Elementium, mortal.\n\nFind and bring me Imperial Qiraji Regalia and the toxic element and I shall infuse weapons of great power.", sourceObjective = "Merithra of the Dream in the Temple of Ahn'Qiraj will create Elementium Infused Armaments for you should you bring her Imperial Qiraji Regalia and 3 Elementium Ore.", progress = "You will strike them down and free us of these bonds.", completion = "Use the item well, {name}. Let them feel the pain that they so dearly wish to inflict upon others.", sourceObjectiveStatus = "unverified-source-field" }
quests[86672] = { id = 86672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperial Qiraji Armaments", description = "We have not sat idly by for a millennium, {name}.\n\nWe have watched these beasts feast on their own when they have exhausted their utility. We have listened as they have plotted and schemed to destroy our world. And we have learned of their own internal treachery.\n\nWeaknesses exist and we know how to use those weaknesses to our advantage.\n\nFind and bring me their ceremonial armaments: Combined with the element created from the volatility of their own God, they will become a force of reckoning.", sourceObjective = "Arygos in the Temple of Ahn'Qiraj will create Elementium Infused Armaments for you should you bring him Imperial Qiraji Armaments and 3 Elementium Ore.", progress = "Seek out what I requested. You will become greater than the sum of your parts, champion.", completion = "Infused with Elementium, these weapons will cut through the Qiraji and their God with incredible ease.", sourceObjectiveStatus = "unverified-source-field" }
quests[86673] = { id = 86673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fall of Ossirian", description = "A terrible menace has been laid to rest. The cruel Ossirian has been vanquished.\n\nThe denizens of Kalimdor would be relieved to know of this victory. Take Ossirian's head and present it to Commander Mar'alith of Cenarion Hold.", sourceObjective = "Deliver the Head of Ossirian the Unscarred to Commander Mar'alith at Cenarion Hold in Silithus.", progress = "Ah, {name}, you have returned! And in one piece, I might add. What news do you bring from Ahn'Qiraj?", completion = "I offer you my highest commendation and your choice of an item of power, {name}. You have done the people of Kalimdor a great service.", sourceObjectiveStatus = "unverified-source-field" }
quests[86674] = { id = 86674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Perfect Poison", description = "My brother and I run the poison operations out of the manor Ravenholdt.\n\nLord Ravenholdt tasked me to track down a new and extremely effective poison compound that can be crafted from the venom sacs of the inhabitants of Zul'Gurub and the Ruins of Ahn'Qiraj.\n\nThere are two particularly venomous beasts residing in those blasted ruins that possess what it is that we might be looking for, {class}. Bring me a venom sac from the beasts Kurinnaxx and Venoxis and we would be eternally grateful.", sourceObjective = "Dirk Thunderwood at Cenarion Hold wants you to bring him Venoxis's Venom Sac and Kurinnaxx's Venom Sac.", progress = "This ain't no smash and grab job, {name}. You're gonna need to bring friends.", completion = "Ravenholdt thanks you, hero! Take your pick!", sourceObjectiveStatus = "unverified-source-field" }
quests[86675] = { id = 86675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Volunteer's Battlegear", description = "The badges you collect from performing combat, logistics and tactical assignments for Cenarion Hold are more than just for show, {name}.\n\nYou'd be wise to hold on to them.  As you prove your loyalty to our organization I can offer you some of the gear we reserve for our closest allies in exchange for those badges.", sourceObjective = "Bring 5 Cenarion Combat Badges, 3 Cenarion Logistics Badges and 7 Cenarion Tactical Badges to Vargus at Cenarion Hold in Silithus. You must also attain Friendly reputation with Cenarion Circle to be able to complete this quest.", progress = "It's in our best interest to keep our most loyal allies well geared, {name}.", completion = "Great work, {name}.  Please accept this on behalf of the Cenarion Circle.  You've certainly earned it, friend!", sourceObjectiveStatus = "unverified-source-field" }
quests[86676] = { id = 86676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veteran's Battlegear", description = "The badges you collect from performing combat, logistics and tactical assignments for Cenarion Hold are more than just for show, {name}.\n\nYou'd be wise to hold on to them.  As you prove your loyalty to our organization I can offer you some of the gear we reserve for our closest allies in exchange for those badges.", sourceObjective = "Bring 7 Cenarion Combat Badges, 4 Cenarion Logistics Badges and 4 Cenarion Tactical Badges to Vargus at Cenarion Hold in Silithus. You must also attain Honored reputation with Cenarion Circle to be able to complete this quest.", progress = "It's in our best interest to keep our most loyal allies well geared, {name}.", completion = "Great work, {name}.  Please accept this on behalf of the Cenarion Circle.  You've certainly earned it, friend!", sourceObjectiveStatus = "unverified-source-field" }
quests[86677] = { id = 86677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalwart's Battlegear", description = "The badges you collect from performing combat, logistics and tactical assignments for Windcaller Proudhorn are more than just for show, {name}.\n\nYou'd be wise to hold on to them.  As you prove your loyalty to our organization I can offer you some of the gear we reserve for our closest allies in exchange for those badges.", sourceObjective = "Bring 15 Cenarion Combat Badges, 20 Cenarion Logistics Badges, 17 Cenarion Tactical Badges and 1 Mark of Remulos to Vargus at Cenarion Hold in Silithus. You must also attain Revered reputation with Cenarion Circle to be able to complete this quest.", progress = "It's in our best interest to keep our most loyal allies well geared, {name}.", completion = "Great work, {name}.  Please accept this on behalf of the Cenarion Circle.  You've certainly earned it, friend!", sourceObjectiveStatus = "unverified-source-field" }
quests[86678] = { id = 86678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion's Battlegear", description = "The badges you collect from performing combat, logistics and tactical assignments for Cenarion Hold are more than just for show, {name}.\n\nYou'd be wise to hold on to them.  As you prove your loyalty to our organization I can offer you some of the gear we reserve for our closest allies in exchange for those badges.", sourceObjective = "Bring 15 Cenarion Combat Badges, 20 Cenarion Logistics Badges, 20 Cenarion Tactical Badges and 1 Mark of Cenarius to Vargus at Cenarion Hold in Silithus. You must also attain Exalted reputation with Cenarion Circle to be able to complete this quest.", progress = "It's in our best interest to keep our most loyal allies well geared, {name}.", completion = "Great work, {name}.  Please accept this on behalf of the Cenarion Circle.  You've certainly earned it, friend!", sourceObjectiveStatus = "unverified-source-field" }
quests[86679] = { id = 86679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shrouded in Nightmare", description = "Corruption seeps from this object.\n\nThere may be a link between this object and the dragons coming forth from the Dream. You must find someone that can decipher the meaning of this item. Perhaps the druids of the Moonglade or Cenarion Hold could assist you further.", sourceObjective = "Find someone capable of deciphering the meaning behind the Nightmare Engulfed Object.\n\nPerhaps a druid of great power could assist you.", progress = "Yes, {race}?", completion = "I must remove the taint from this object. This may shed some light on my recent failures to delve into the Dream. Give it to me.", sourceObjectiveStatus = "unverified-source-field" }
quests[86680] = { id = 86680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waking Legends", description = "The waters of Lake Elune'ara should dissolve the nightmares engulfing this object. Give me a moment to perform the cleansing, {name}.", sourceObjective = "Wait for Keeper Remulos at the Moonglade to cleanse the Nightmare Engulfed Object.", progress = "You have seen that which you must.", completion = "Take his ring, {name}. It has served its purpose for Malfurion. It shall now serve a new purpose for you...", sourceObjectiveStatus = "unverified-source-field" }
quests[86724] = { id = 86724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dust to Dust", description = "{name}, lend me your ear. The Captain's wounds grow ever more grievous. The camp celebrates each victory with their usual jubilance, but I cannot join in their cheers. Not when I've seen the wounds he hides beneath his armor. \n\nAn Infection? No no, I would say it's much closer to... an infestation. I'm preparing a concoction, but there's one key ingredient I still need--Silithyst. \n\nI need it, and quickly. Based on my inspection of the Captain's condition, I fear he won't last much longer without it.", sourceObjective = "Find and deliver 5 Silithyst to the Silithyst Extractor then speak with Apothecary Quinard at the Horde encampment near Hive'Regal.", progress = "Careful {name}. From what I've gleaned in our scouting reports, the Alliance are beginning to understand the value of the sand. \n\nWith this, I advise you to steel yourself. There are now two types of worms out there roaming the desert.", completion = "Excellent. You've gathered it all, and not a moment too soon. I will prepare the concoction for Captain Krug immediately. \n\nI can't reward your bravery with coin, but I can bestow you with some of my knowledge. I would part with the notes I've used to treat the soldiers and fill their bellies, for a price of course.", sourceObjectiveStatus = "unverified-source-field" }
quests[86725] = { id = 86725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dust to Dust", description = "Ah yes, the dangers of the desert. No, not the sweltering heat, not the unbearable sunlight, not the sand crawling up into your robes, not the freezing nights.\n\nThe other dangers! The bugs, and now the bothersome brutes. Our reconnaissance has reported the Horde are gathering dirt! \n\nI usually wouldn't call this out of the ordinary for them, but Silithyst? I would rather they not uncover the secrets of the sand. As Chief Expeditionary Requisitioner I am requesting a competing order! Get me that dirt!", sourceObjective = "Find and deliver 5 Silithyst to the Silithyst Extractor then speak with Chief Expeditionary Requisitioner Enkles at the Alliance encampment near Hive'Zora.", progress = "What are you still doing here {name}? My precognition potion told me you were the person for the job! \n\nWe've been able to distill the essence of the Silithus crystals into a potion that grants the user the ability to have limited precognition. \n\nAh, my apologies, but I have not been authorized to make these potions available to you at this moment.", completion = "Very good {name}! Allow me to simply input this transaction into my logbook...\n\nAnd here you are. If we have any other matters of requisition, I will direct them to you, and as Chief Expeditionary Requisitioner, I do expect assistance. \n\nI unfortunately am not authorized to pay you, but I didn't get to where I am now by not rewarding my underlings! I have in my possession many recipes that were requested but never distributed. As reward, I will allow you to purchase from my library of abandoned knowledge.", sourceObjectiveStatus = "unverified-source-field" }
quests[86760] = { id = 86760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Beast Deck", description = "Now that you have gathered all of the Beast cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"   You have heard that this faire alternately stops at Mulgore and Goldshire every few months, so you will have to wait until they are here next.", sourceObjective = "Return the Beast Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of beasts!   Congratulations!", completion = "So you have put together a deck of Beasts.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[86761] = { id = 86761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Warlords Deck", description = "Now that you have gathered all of the Warlord cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"   You have heard that this faire alternately stops at Mulgore and Goldshire every few months, so you will have to wait until they are here next.", sourceObjective = "Return the Warlords Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of warlords!   Congratulations!", completion = "So you have put together a deck of Warlords.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[86762] = { id = 86762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Elementals Deck", description = "Now that you have gathered all of the Elemental cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"   You have heard that this faire alternately stops at Mulgore and Goldshire every few months, so you will have to wait until they are here next.", sourceObjective = "Return the Elementals Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of elementals!   Congratulations!", completion = "So you have put together a deck of Elementals.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[86763] = { id = 86763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Portals Deck", description = "Now that you have gathered all of the Portal cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"   You have heard that this faire alternately stops at Mulgore and Goldshire every few months, so you will have to wait until they are here next.", sourceObjective = "Return the Portals Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of portals!   Congratulations!", completion = "So you have put together a deck of Portals.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[86964] = { id = 86964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Gold and Glory!", description = "Calling all adventurers and treasure hunters! Let it be known that the Kirin Tor has authorized the disbursement of considerable funds to any individuals who are able to descend into the crypts below Karazhan and recover a particular  magical artifact. Any other treasure, curios, or coin recovered is of no consequence to the order, and may be retained as additional compensation.  Interested parties should report to... \n\n<The bottom of the note has been torn off and the rest of the details are missing.>", sourceObjective = "It appears as if someone was looking to hire adventurers to recover something valuable from the Karazhan Crypts in Deadwind Pass. You can't be sure who posted this flyer or where to find them, but the idea of a considerable reward from a well-established and deep-pocketed organization such as the Kirin Tor, as well as a cache of hidden treasure up for the taking is an admittedly interesting prospect.\n\nTravel to Deadwind Pass and investigate the Crypts behind Karazhan tower.", completion = "The human lying before you is indeed quite dead. She does not appear to have any obvious wounds or trauma. The only odd thing about the body is a look of intense terror on her face. It's almost as if this woman died of fright...", sourceObjectiveStatus = "unverified-source-field" }
quests[86965] = { id = 86965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Ordinary Shadows", description = "A sudden and oppressive darkness begins to fall over you as you kneel down. You notice that all nearby light seems to darken and fade as the darkness seems to reach out to you. These are no natural shadows. \n\nA quick glance over to the entrance to the crypt nearby tells you without doubt that this malign darkness is coming from the crypt itself, with inky black tendrils seeking more light to snuff out. You shudder as hairs on the back of your neck stand up.", sourceObjective = "The gloom seeping from the entrance of the crypt seems to defy all normal logic and reason. No light enters or deters the darkness, and no light inside seems to escape it. You strongly suspect that venturing into the crypt as you are now could be the end of you.\n\nYou'll need to somehow find a way to get past this darkness if you wish to proceed. You seem to recall that there is an Agent of Dalaran at a camp to the north. Perhaps she knows more about the dead adventurer and this strange darkness?", completion = "<Agent Keanna looks up at you and frowns slightly.>\n\nLook, I told the last group to come through here asking about the crypts that I don't have any information about the bounty my order placed upon whatever cursed treasure lies beneath that old tower. My area of expertise lies elsewhere and I'm not authorized to make any large expenditures on behalf of the order. \n\nIf there's nothing else, I'd like to return to my research.", sourceObjectiveStatus = "unverified-source-field" }
quests[86966] = { id = 86966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Survivors", description = "Oh, I see. Yes, the body you claim to have found does indeed seem to match my recollection of one of the adventurers who passed through here recently. There were five of them, as I recall. I urged them against going any further, but they could not be dissuaded. It seems my warnings were well-founded as I've not seen any of their number pass by since. I feared the worst and, well...\n\nYou say she was the only body you found? If that's true, mayhap there are other survivors somewhere in the pass?", sourceObjective = "Search for any survivors of the unfortunate adventuring party and try to learn what you can about what happened in the crypt.", completion = "The man stirs slightly as you approach, opening a single eyelid almost imperceptibly to peer at you. Initially he seemed seriously injured, but now you aren't entirely sure...", sourceObjectiveStatus = "unverified-source-field" }
quests[86967] = { id = 86967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Rescue", description = "<The man's one open eye locks with yours.>\n\nPsst, hey you. Yes, you! Think you can get me out of here? I've been lying here playing dead for hours but its only a matter of time before these damned ogres remember I'm here and come to eat me, or worse! \n\nThis cage is locked up pretty tight but one of these brutes should have the key. See if you can find one and let me out. I'd certainly be in your debt. \n\nI'm going to keep playing dead while you get to work. Now go... quietly!", sourceObjective = "Find the key to the cage in the Deadwind ogre cave and free the injured adventurer inside.", completion = "How on Azeroth did I beat you back here bloody and concussed?\n\n<Harrison Jones shakes his head.>\n\nYou sure you are up for this, kid?", sourceObjectiveStatus = "unverified-source-field" }
quests[86968] = { id = 86968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Are You Afraid of the Dark?", description = "Really can't thank you enough for the help back there. You really saved my bacon. \n\nI've been chatting with this nice young woman while waiting for you and I think she might have some ideas to help you get into that forsaken crypt, if you really do insist on pushing your luck.\n\nI'm getting ahead of myself. though. I believe I owe you some information.", sourceObjective = "Listen to Harrison Jones while he tells you what happened in Karazhan Crypts.", completion = "So it appears that Jones' group successfully entered the crypt and happened upon a substantial cache of riches. The darkness both you and he described certainly seems magical in nature. Clearly their clumsy looting seemed to have triggered a reaction from something malign.\n\nI've consulted my spell tomes and I think I might have a potential solution to get you through that darkness, should you still feel brave enough to proceed. Come, let's speak further on the matter.", sourceObjectiveStatus = "unverified-source-field" }
quests[86969] = { id = 86969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hypothesis", description = "I think I can fashion a magical totem of sorts that should allow you to pierce this malign darkness and at least allow you to explore the crypts. I don't have all of the components with me, however. Some of this might not be easy to find, but judging by what I've seen from you so far, I trust that you are resourceful enough to secure what is needed.", sourceObjective = "Consult the list of materials needed and bring Agent Keanna the components requested.", progress = "Have you managed to recover the components I require?", completion = "Excellent. This binding is simple enough, let me just.... There! I think that should do it.\n\nThis magical torch should allow you to pierce the malign darkness enough to at least see and explore the Crypt. Be advised however, the wisp possessing this item has a will of its own. While I have bound it to this object and to this specific purpose, I cannot be entirely sure how it will...  behave when you reach the crypt. \n\nBe on your guard when you arrive. We can't fully predict what will occur.", sourceObjectiveStatus = "unverified-source-field" }
quests[86970] = { id = 86970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testing Our Hypothesis", description = "I think it wise that we put this device to the test before you commit fully to your delve down into the darkness of the Crypts. Take the torch to the edge of the magical darkness and activate it. See if it serves its purpose and provides illumination, and more importantly, discern how it behaves when exposed to this magic.\n\nThis totem was bound with a specific purpose and should be compelled to adhere to that purpose, but there's no real telling until we get there and test this hypothesis.", sourceObjective = "Travel to the entrance to the Karazhan Crypts, use the Enchanted Firebrandtorch, and see what happens. Return to Agent Keanna after you've completed the test.", progress = "What did our test reveal?", completion = "This is good news. Not only did the torch successfully dispel the lesser darkness outside the crypt, but the binding compelled it to rush unbidden into the crypt to continue to fulfill its purpose. \n\nNow that the malign darkness outside of the crypt is gone, I suspect you should be able to enter safely. Judging by this man's tale there's no telling what you'll find inside, so do be careful.\n\nGood luck.", sourceObjectiveStatus = "unverified-source-field" }
quests[86971] = { id = 86971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curious Karazhan Curios!", description = "Now that you've figured out a way into the crypt, I'd like to ask you a favor. In case it wasn't obvious I'm an archaeologist in employ of the Royal Library of Stormwind. I collect artifacts and relics from all across the world for academic research and study, and I'm keenly interested in any such curios you may come across within the depths of the crypt. Bring any that you think might be interesting back to me, and I'll make it worth your while.", sourceObjective = "Bring a Karazhan Curio to Harrison Jones in Deadwind Pass.", progress = "What have you got for me, {name}?", completion = "This is an excellent find! If you should happen upon any more artifacts like this, bring them to me here and I'll ensure you are appropriately compensated for your efforts.", sourceObjectiveStatus = "unverified-source-field" }
quests[86972] = { id = 86972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curious Karazhan Curios!", description = "Now that you've figured out a way into the crypt, I'd like to ask you a favor. In case it wasn't obvious I'm an archaeologist in employ of the Royal Library of Stormwind. I collect artifacts and relics from all across the world for academic research and study, and I'm keenly interested in any such curios you may come across within the depths of the crypt. Bring any that you think might be interesting back to me, and I'll make it worth your while.", sourceObjective = "Bring a Karazhan Curio to Harrison Jones in Deadwind Pass.", progress = "Remember, I'm on the hunt for any artifact or treasure that you may find. There are untold treasures in that crypt, so keep your eyes peeled!", completion = "This is an excellent find! If you should happen upon any more artifacts like this, bring them to me here and I'll ensure you are appropriately compensated for your efforts.", sourceObjectiveStatus = "unverified-source-field" }
quests[87283] = { id = 87283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Violet Satchel", description = "You've found a small violet satchel that appears to bear the mark of the Kirin Tor. Despite your best efforts, you can't seem to find a way to lift the flap and see what is inside, however. The note on the body of the adventurer where you found this suggests that it might be the property of Archmage Kir-Moldir of Dalaran. It might be worth your while to seek out the Archmage and return his property... and claim the promised reward.", sourceObjective = "Find Archmage Tarsis Kir-Moldir and return the The Violet Satchel to him.", progress = "The Archmage seems not to hear you...", completion = "What is that you have there? Is it... could it be? \n\n<The Archmage quickly snatches the satchel from you. He whispers an incantation and empties the contents into his hands, revealing two small red gemstones.>\n\nThe eyes! Yes, the eyes! I have them! Thank you. Please, leave me now... Go! Go before I am forced to destroy you!\n\n<The hard look in his eyes tells you that he is quite serious. As you begin to back away the Archmage turns away, hunching over and clutching the gemstones tightly to his chest.>", sourceObjectiveStatus = "unverified-source-field" }
quests[87360] = { id = 87360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fall of Kel'Thuzad", description = "The phylactery is all that remains of the master of Naxxramas. Your better judgment dictates that you destroy the phylactery, preventing the lich from ever reforming. Thankfully, you seldom listen to that internal voice of reason.\n\nSomeone at Light's Hope will pay you hugely for this artifact. Who cares if Kel'Thuzad regenerates to full power?", sourceObjective = "Take the Phylactery of Kel'Thuzad to Light's Hope Chapel in the Eastern Plaguelands.", progress = "BLESSED LIGHT! What foulness do you hold, boy?", completion = "In all my days of living I would have never expected to see this...\n\n<Father Montoy appears to be salivating.>\n\nOh yes, you will be rewarded dear boy. You will be greatly rewarded. Give it here. Now!", sourceObjectiveStatus = "unverified-source-field" }
quests[87361] = { id = 87361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Laid to Rest", description = "Plucked from a Shadow of Doom, the heart faintly pulses and vibrates.\n\nYou move to put it in your bag, but are struck with an overwhelming sense of anger, fear, dread, and then... sadness.\n\nAs these feeling subside, you feel as though you've just lived another life.\n\nPerhaps someone at Light's Hope Chapel can shed some light on what you just felt.", sourceObjective = "See if anyone can assist you at Light's Hope Chapel in Eastern Plaguelands.", progress = "You need not explain, {name}.\n\nYour presence here and this orb tell me all I need to know.\n\nThe darkness has tested you, {name}.\n\nYou're lucky. The scourge and their curses are nothing to toy with.\n\nThe Light follows you.", completion = "Almost none who touch these cursed objects are still in possession of their faculties.\n\n<Although his expression is unchanged, tears begin to trail down his face as you hand him the heart>\n\nAh... this one doesn't want to go. They were a {class}... like yourself... \n\n{name}, if you are willing to bear the weight, I may be able to assist you. I can engrave this restless soul onto your armor...\n\nI have found that just like the weight of the world, the best place to carry a soul - is on your shoulders.", sourceObjectiveStatus = "unverified-source-field" }
quests[87362] = { id = 87362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hope Begins in the Dark", description = "Naxxramas poses a threat like nothing you've faced before. It is the seat of Kel'Thuzad's power, and contains horrors unknown to even the most battle-scarred among the Argent Dawn.\n\nTake this seal. \n\nWhen you venture within the necropolis, you carry the weight of our hopes, {name}. It's only right that you also carry our strength.", sourceObjective = "Receive the Seal of the Dawn.", completion = "This Seal will empower the equipment you recover from inside Naxxramas. \n\nKeep it close and use it well.", sourceObjectiveStatus = "unverified-source-field" }
quests[87364] = { id = 87364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seal the Deal", sourceObjective = "Collect Remnants of Valor within Naxxramas.", progress = "Truthfully, {name}, there may be a way to improve the power of your seal.\n\nWhen we purify the remains of powerful lieutenants of the Scourge, a small amount of holy energy is not only retained, but tempered. This energy can be forged into strength.\n\nVenture deeper inside Naxxramas, hero, and retrieve remnants of these Scourge lieutenants for me. In turn, I can empower your seal.", completion = "You've done well in bringing these to me, {name}. \n\nI wonder how many of these came from our fallen brethren? Were they still in there, somewhere? I have to believe that they'd want us to prevent others from becoming like them. A small comfort, perhaps.  \n\nAllow me to empower your seal.", sourceObjectiveStatus = "unverified-source-field" }
quests[87365] = { id = 87365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valor Grows by Daring", sourceObjective = "Collect Remnants of Valor within Naxxramas.", progress = "Your seal has a long way to go if you mean to see it reach its potential. Bring me more Remnants of Valor, and I'll continue to provide you with the strength to protect our world. \n\nRemember, hero, that the dead cannot cry out for justice. It is the duty of the living to do so for them.", completion = "Well done. As before, this will only take a moment.", sourceObjectiveStatus = "unverified-source-field" }
quests[87366] = { id = 87366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knight Time", sourceObjective = "Collect Remnants of Valor within Naxxramas.", progress = "Each slain minion of the Scourge is a soul freed, {name}. Never forget the good you do, even - no, especially when the battle feels hopeless. As long as we stand against him, the Lich King's armies cannot stop us. \n\nI suspect you know the drill by now. Provide me with more remnants, and I will continue to empower your seal.", completion = "Justice seeks no reward, {name}. \n\nI know you do, though. Take this.", sourceObjectiveStatus = "unverified-source-field" }
quests[87367] = { id = 87367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Light", sourceObjective = "Receive the Seal of the Dawn.", progress = "Each time we empower your seal, we take a step towards ending Kel'Thuzad's incursion. \n\nStay strong, and we'll have freed Azeroth from the Lich King and his lieutenants in no time.", completion = "You're a true hero, {name}. The Ashbringer himself would have been impressed.", sourceObjectiveStatus = "unverified-source-field" }
quests[87368] = { id = 87368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Product of Faith", sourceObjective = "Receive the Seal of the Dawn.", progress = "I shudder to think of the horrors you've faced to come this far. You're an inspiration to the Argent Dawn, and I can only pray that you continue to aid us in this manner. \n\nBring me more Remnants of Valor, and I'll empower your seal. I believe there's a way to go before you realize your potential.", completion = "Well done, {name}. To purify the fallen would be a worthy endeavor in and of itself, even if no reward were promised. \n\nOf course, that's not the case for you! Take your newly-empowered seal.", sourceObjectiveStatus = "unverified-source-field" }
quests[87369] = { id = 87369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cultivating Faith", sourceObjective = "Receive the Seal of the Dawn.", progress = "I never imagined that the Scarlet Crusade and the Argent Dawn could put aside their differences and fight for a common good, but here we are. \n\nTime and again, you've proven that our gamble's paid off. Retrieve more Remnants of Valor, champion. I feel that we're close to delivering our final blow to Kel'Thuzad and his ilk.", completion = "Once again, I thank you, and once again, I'll prove my gratitude by empowering your seal.", sourceObjectiveStatus = "unverified-source-field" }
quests[87377] = { id = 87377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never at Rest", description = "Bring me any doomed souls that cross your path, {name}.\n\nLet me rephrase that - you MUST bring them to me.\nMY duty is to stay and guide the souls of the lost. YOUR duty is to bring them to me.\n\nA word of advice, never handle more than one soul at a time. Trust me, your soul can only handle so much, and your mind... well... it can handle even less.\n\nThis burden is now yours. Because you can, you must. \n\nConsider this a moral obligation.", sourceObjective = "Bring another Heart of Doom to Brother Luctus at Light's Hope Chapel in Eastern Plaguelands.", progress = "The scourge never rests, so we must never rest, {name}.", completion = "{name}, with every heart returned, I stand humbled. Some of the souls have been from powerful warriors. Some seemed as though they were indomitable... and yet... they fell.\n\nScourge overrunning them, corruption seeping into their minds, or in some cases - they willingly submitted.\n\nSuch great strength - snuffed out.\n\nAnd now, thanks to you, they preserve their final shred of valor. \n\nWithout you, the horrors of their deaths would outweigh the heroics of their lives.", sourceObjectiveStatus = "unverified-source-field" }
quests[87433] = { id = 87433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argent Dawn Plate Gloves", progress = "If you bring me thirty necrotic runes, I will give you your choice of hand protection in return. These should prove valuable in our fight against the undead Scourge.", completion = "You've done well, {name}. Take your pick of hand protection in thanks for your efforts." }
quests[87434] = { id = 87434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argent Dawn Plate Gloves", progress = "If you bring me thirty necrotic runes, I will give you your choice of hand protection in return. These should prove valuable in our fight against the undead Scourge.", completion = "You've done well, {name}. Take your pick of hand protection in thanks for your efforts." }
quests[87435] = { id = 87435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argent Dawn Mail Gloves", progress = "If you bring me thirty necrotic runes, I will give you your choice of hand protection in return. These should prove valuable in our fight against the undead Scourge.", completion = "You've done well, {name}. Take your pick of hand protection in thanks for your efforts." }
