quests[87440] = { id = 87440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argent Dawn Cloth Gloves", progress = "If you bring me thirty necrotic runes, I will give you your choice of hand protection in return. These should prove valuable in our fight against the undead Scourge.", completion = "You've done well, {name}. Take your pick of hand protection in thanks for your efforts." }
quests[87441] = { id = 87441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atiesh, Greatstaff of the Guardian", description = "This final task will be the most difficult of all, {name}. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras.\n\nTake the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.", sourceObjective = "Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him.", progress = "I must not interfere, {race}.", completion = "The magnitude of this accomplishment must not be understated, {name}. You have done what most would have thought to be impossible. Alas, it was fated. The staff has made its choice...", sourceObjectiveStatus = "unverified-source-field" }
quests[87442] = { id = 87442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atiesh, Greatstaff of the Guardian", description = "This final task will be the most difficult of all, {name}. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras.\n\nTake the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.", sourceObjective = "Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him.", progress = "I must not interfere, {race}.", completion = "The magnitude of this accomplishment must not be understated, {name}. You have done what most would have thought to be impossible. Alas, it was fated. The staff has made its choice...", sourceObjectiveStatus = "unverified-source-field" }
