quests[87444] = { id = 87444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atiesh, Greatstaff of the Guardian", description = "This final task will be the most difficult of all, {name}. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras.\n\nTake the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.", sourceObjective = "Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him.", progress = "I must not interfere, {race}.", completion = "The magnitude of this accomplishment must not be understated, {name}. You have done what most would have thought to be impossible. Alas, it was fated. The staff has made its choice...", sourceObjectiveStatus = "unverified-source-field" }
quests[87459] = { id = 87459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scarlet Activities", description = "While we play nice with the Scarlet Crusaders here, they continue to behave suspiciously elsewhere. Some of my contacts in Tirisfal tell me of a daring Scarlet Crusade incursion into the heart of the Undercity itself, and we've received reports from our scouts of large caravans moving supplies through the plaguelands. A band of elite scarlet forces has been spotted near the Crusader Outpost in Tirisfal Glades, between the Balnir Farmstead and Venomweb Vale. If you would, go and see what you can find there.", sourceObjective = "Travel to the area near the Crusader Outpost northwest of The Bulwark in Tirisfal Glades and investigate for signs of recent Scarlet Crusade activity. Bring any information you recover back to Leonid Barthalomew the Revered.", progress = "How goes your mission, {name}?", completion = "I see. So it seems the Crusade abducted someone from the city, and someone important, at that. This is most concerning. Thank you, {name}.  For now, do nothing and speak to no one of this. Our alliance with the Scarlet Crusade is tenuous, but we need all the help we can get to deal with the threat of Naxxramas at the moment. \n\nI will follow up on this on my own. I may call upon you in the future for more aid in this. Until then, go with the light.", sourceObjectiveStatus = "unverified-source-field" }
quests[87493] = { id = 87493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unrest at Tyr's Hand", description = "There's been an interesting development, {name}. It seems that while the Scarlet Crusade's focus was aimed at Naxxramas, there's been some sort of unrest in the ranks at Tyr's Hand. Details are spotty for now, but from what we understand, there has been some infighting amongst the crusaders.\n\nI'd like to send you to the camp west of Tyr's Hand to assess the situation out for us. Let us know what you find as soon as possible.", sourceObjective = "Scout out the Scarlet Base Camp west of Tyr's Hand  in Eastern Plaguelands and try to discern what is happening with the Scarlet Crusade forces there.", completion = "Greetings, {name}. I'm glad to see you again. I do wish it were under better circumstances, however.", sourceObjectiveStatus = "unverified-source-field" }
quests[87497] = { id = 87497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Schism", description = "I'll cut straight to the chase; the Tyr's Hand enclave is no longer under our control. While we were away at Naxxramas, a force of  hostile crusaders came in from the city of Stratholme and took control of the stronghold. We've been barred entry and any emissaries we send in do not return.\n\nI am loathe to ask for external assistance, but something is very wrong and I don't know if we can reclaim the enclave alone.", sourceObjective = "Speak with Beatrix to learn more about the situation in the Scarlet Enclave at Tyr's Hand and report back to Leonid Barthalomew the Revered at Light's Hope Chapel once you've learned more about what is happening.", progress = "What have you learned?", completion = "The developments at Tyr's Hand are... certainly interesting. Abbendis likely dead, Balnazzar returned. While there is part of me that would prefer to sit back and watch the Scarlet Crusade reap what they have sown, I feel that no matter the outcome the Argent Dawn would likely be drawn into conflict. Weakened as we are following the Naxxramas campaign, Lord Tyrosus would prefer our involvement come on our terms rather than having our hand forced.\n\nAlso... did you say that Inquisitor Caldoran was there?", sourceObjectiveStatus = "unverified-source-field" }
quests[87498] = { id = 87498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scarlet Reclamation", description = "<Leonid's expression darkens when you confirm that Caldoran is present at the Scarlet Base Camp. After a moment, he regains his composure.> \n\nThank... thank you, {name}. For now, continue to assist Beatrix if you are willing. I will confer with Lord Tyrosus and develop contingencies should the Argent Dawn need to become directly involved. I pray that the situation is not as dire as we've been led to believe but if we need to step in and put an end to this, we will be ready.", sourceObjective = "Return to Commander Beatrix at the Scarlet Base Camp west of Tyr's Hand.", completion = "So you will aid us? I confess I am relieved. I've seen you and your allies' capabilities first hand and I'm pleased to have you on our side in this. I had hoped the Argent Dawn would lend their aid directly, but I am grateful to have your assistance none the less.\n\nSpeak with Inquisitor Caldoran on the hill nearby. He can get you started.", sourceObjectiveStatus = "unverified-source-field" }
quests[87502] = { id = 87502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering Intelligence", description = "I am not pleased to engage you for aid. You consort with the heretic and the unclean and it is beneath me and our sacred order to entertain your presence here. However... you seem adequately capable and will prove to be a useful instrument here for our needs.\n\nGo to Tyr's Hand and scout the cathedral there before moving deeper into New Avalon to scout the rear keep and mage tower. Return here without delay and report what you find. We need to know what we are up against.", sourceObjective = "Enter Tyr's Hand in Eastern Plaguelands and scout out the central cathedral, as well as the mage tower and keep inside of New Avalon before returning to Caldoran at the Scarlet Base Camp. \n\nA direct incursion is possible but may be dangerous. Speak with Inquisitor Jociphine at the Scarlet Base Camp if you'd prefer a more subtle approach.", progress = "Have you completed your mission? If not, why are you standing here idly speaking with me?", completion = "<Caldoran grunts at you curtly when you finish delivering your report.>\n\nThe buildup of forces in New Avalon is concerning, but their numbers are not insurmountable. \n\nIt also seems that Dathrohan--or should I say, Balnazzar--is consolidating his power at the central Cathedral, and his usage of foul magics to seal the entrance confirms that he is up to something in there. That monster desecrates our holy ground and  I will see him dead by my hand. I swear it upon my life.", sourceObjectiveStatus = "unverified-source-field" }
quests[87506] = { id = 87506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weakening The Defenses", description = "While you were away we finalized our attack plans on Tyr's Hand. We will execute a frontal assault as well as a flanking strike, which I myself will lead. Before we fully commit we'll need to weaken the forward defenses. I'm sending you back in to Tyr's Hand to take out as many of the enemy Siege Commanders as possible, as they are the key organizers of the enclave's defenses. \n\nI'm leaving to join my forces at our position now. You'll report to Commander Beatrix when you return. \n\nDon't fail.", sourceObjective = "Enter Tyr's Hand in Eastern Plaguelands, slay three Scarlet Siege Commanders.", progress = "Were you successful in your mission?", completion = "Caldoran and his guard have sent the signal that they are in position and ready to support a direct attack. \n\nWhile you were away an Argent Dawn messenger arrived to deliver a message, then hurried away quickly. It seems that there is some trouble at Light's Hope Chapel, and you are needed back there urgently. I can't ask you for anything more as you've already been invaluable in this effort.  Thank you for your aid, {name}. We are as ready as we'll ever be now.", sourceObjectiveStatus = "unverified-source-field" }
quests[87508] = { id = 87508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Lord Tyrosus", description = "Please, {name}, a messenger just arrived. You must return to Light's Hope Chapel with all haste! We are under attack and Lord Maxwell Tyrosus has requested your presence at once.", sourceObjective = "Speak with Lord Maxwell Tyrosus at Light's Hope Chapel in Eastern Plaguelands.", completion = "We have been attacked! Some sort of dragon-like... abomination flew in fast from the direction of the Scarlet Enclave and hit us hard. I've seen dragons before but I've never seen anything like this.\n\nThe strangest part is that the dragon just... left. It hit us with a single terrible blast and then just flew away. This is a blessing, to be sure--but is deeply unsettling. We were caught completely unaware. It could have inflicted enormous damage but it seemed to choose not to.", sourceObjectiveStatus = "unverified-source-field" }
quests[87509] = { id = 87509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wrath of the Dawn", description = "Regardless of the reason that beast withdrew back to the enclave, we will not give it another chance to destroy us. It seems that our hand is forced and we must now commit the full fury of the Argent Dawn to the cause of ending the threat of the Scarlet Enclave.  \n\nGo back to the Scarlet Base Camp and meet back up with Beatrix. Let her know that she has our support... for now.", sourceObjective = "Report back to Commander Beatrix at the Scarlet Base Camp in Eastern Plaguelands and make ready to retake the Scarlet Enclave.", progress = "I saw smoke rising from the direction of Light's Hope, what has happened?", completion = "Some sort of beast attacked Light's Hope? That is bold of Balnazzar. Too bold, as now the Argent Dawn has committed to our cause. I won't lie to you and tell you I am not relieved to receive their assistance. I don't think we can take the enclave with the forces at our command now. \n\nWe're in the endgame now, {class}. Prepare your forces.", sourceObjectiveStatus = "unverified-source-field" }
quests[87516] = { id = 87516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decapitation Strike", description = "Our forces are mustered and we will move into positions to begin the forward attack while your forces sneak around to the rear of the cathedral using the mountain path.\n\nOnce inside make your way to the abbey and ring the bell to signal the attack. \n\nYou'll be in the thickest of the fighting until we arrive to relieve you, so take care.", sourceObjective = "Enter the Scarlet Enclave via the mountain path and engage the Tyr's Hand defenders. Ring the bell inside of the abbey to create confusion and signal Beatrix's forces to attack. \n\nOnce the bell is rung, confront Balnazzar and destroy him.", progress = "This was very nearly a complete disaster...", completion = "We have been betrayed! After Balnazzar fell, Beatrix assumed control of the leaderless defenders and immediately turned her newly bolstered forces on us! Casualties were heavy but we hit back hard and were able to fall back and regroup. We feared the worst for your force until our scouts reported you were here.\n\nI don't know what Beatrix and Caldoran are playing at, but at this point I'm ready to put down anyone I see wearing red and leave the the light to sort them out.", sourceObjectiveStatus = "unverified-source-field" }
quests[87517] = { id = 87517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Red = Dead", description = "It seems that the beast that attacked light's hope is Caldoran's pet and the attack on Light's Hope was merely a ruse to draw our forces out and commit us to this attack. Caldoran and Beatrix sought to use us to create a distraction and remove a rival in Balnazzar, and then turn on us and remove us as a presence in the Plaguelands after they regained control. \n\nWe don't have all of the answers and it's looking grim, but we will put these dogs down for this treachery.", sourceObjective = "Join the battle and gain access to the inner portion of the Scarlet Enclave. Engage High Commander Beatrix's forces and defeat her, then slay the dragon, Solistrasza inside of the inner walls to the enclave.", progress = "What in the light's name has the Scarlet Crusade been doing behind these walls?", completion = "What we've discovered here is beyond the pale. A new plague? A lightbound dragon? Siphoning the souls of the pious to fuel their light-infused weapons? Such abuse of the light is sickening, and I shudder to think what other power Caldoran may yet have at his disposal. The way he destroyed Balnazzar tells me that he's been up to something. Such raw power is beyond even the strongest of paladins. \n\nAll the same, it ends now. No quarter will be given. These atrocities are beyond redemption.", sourceObjectiveStatus = "unverified-source-field" }
quests[87518] = { id = 87518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fall of the Grand Crusader", description = "The path forward now is simple and brutal. Breach the inner sanctum of the Scarlet Enclave and confront the new self-proclaimed \"Grand Crusader\"  Baelin Caldoran. Bring him to justice for his crimes. We'll stay here and secure this position to ensure that no remnant forces harass you from behind. \n\nBring that monster to justice.", sourceObjective = "Slay Grand Crusader Baelin Caldoran in the Scarlet Enclave's inner sanctum.", completion = "Caldoran is no more but the victory is bittersweet. It has been a bloody day. With the Scarlet Crusade's remaining forces scattered and the Scarlet Enclave in flames, we've done a great thing here. There's still much work to do in the Plaguelands, but at least we have one less adversary to worry about for now. As far as I am concerned, that is a cause for celebration.\n\nFor the Light! For Lordaeron! For the Dawn!", sourceObjectiveStatus = "unverified-source-field" }
quests[87520] = { id = 87520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antithesis of the Light", description = "The smooth black artifact before you pulsates ominously. It's as if this object seems to draw in and consume all nearby light. Your intuition tells you that this object is dangerous, and that touching it with your bare hands would be ill advised.\n\nYou wrap the object in a cloth and stash it in your pack. Lord Maxwell Tyrosus at Light's Hope Chapel may be interested in this.", sourceObjective = "Bring the Strange Black Crystal to Lord Maxwell Tyrosus at Light's Hope Chapel.", sourceObjectiveStatus = "unverified-source-field" }
quests[88654] = { id = 88654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Full Shipment", progress = "Do you have something for me?", completion = "Everything's accounted for! Thank you, {name}. These supplies are critical for the front lines." }
quests[88713] = { id = 88713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never at Rest", description = "Bring me any doomed souls that cross your path, {name}.\n\nLet me rephrase that - you MUST bring them to me.\nMY duty is to stay and guide the souls of the lost. YOUR duty is to bring them to me.\n\nA word of advice, never handle more than one soul at a time. Trust me, your soul can only handle so much, and your mind... well... it can handle even less.\n\nThis burden is now yours. Because you can, you must. \n\nConsider this a moral obligation.", sourceObjective = "Bring another Heart of Doom to Brother Luctus at Light's Hope Chapel in Eastern Plaguelands.", progress = "The scourge never rests, so we must never rest, {name}.", completion = "{name}, with every heart returned, I stand humbled. Some of the souls have been from powerful warriors. Some seemed as though they were indomitable... and yet... they fell.\n\nScourge overrunning them, corruption seeping into their minds, or in some cases - they willingly submitted.\n\nSuch great strength - snuffed out.\n\nAnd now, thanks to you, they preserve their final shred of valor. \n\nWithout you, the horrors of their deaths would outweigh the heroics of their lives.", sourceObjectiveStatus = "unverified-source-field" }
quests[88714] = { id = 88714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never at Rest", description = "Bring me any doomed souls that cross your path, {name}.\n\nLet me rephrase that - you MUST bring them to me.\nMY duty is to stay and guide the souls of the lost. YOUR duty is to bring them to me.\n\nA word of advice, never handle more than one soul at a time. Trust me, your soul can only handle so much, and your mind... well... it can handle even less.\n\nThis burden is now yours. Because you can, you must. \n\nConsider this a moral obligation.", sourceObjective = "Bring another Heart of Doom to Brother Luctus at Light's Hope Chapel in Eastern Plaguelands.", progress = "The scourge never rests, so we must never rest, {name}.", completion = "{name}, with every heart returned, I stand humbled. Some of the souls have been from powerful warriors. Some seemed as though they were indomitable... and yet... they fell.\n\nScourge overrunning them, corruption seeping into their minds, or in some cases - they willingly submitted.\n\nSuch great strength - snuffed out.\n\nAnd now, thanks to you, they preserve their final shred of valor. \n\nWithout you, the horrors of their deaths would outweigh the heroics of their lives.", sourceObjectiveStatus = "unverified-source-field" }
quests[88715] = { id = 88715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never at Rest", description = "Bring me any doomed souls that cross your path, {name}.\n\nLet me rephrase that - you MUST bring them to me.\nMY duty is to stay and guide the souls of the lost. YOUR duty is to bring them to me.\n\nA word of advice, never handle more than one soul at a time. Trust me, your soul can only handle so much, and your mind... well... it can handle even less.\n\nThis burden is now yours. Because you can, you must. \n\nConsider this a moral obligation.", sourceObjective = "Bring another Heart of Doom to Brother Luctus at Light's Hope Chapel in Eastern Plaguelands.", progress = "The scourge never rests, so we must never rest, {name}.", completion = "{name}, with every heart returned, I stand humbled. Some of the souls have been from powerful warriors. Some seemed as though they were indomitable... and yet... they fell.\n\nScourge overrunning them, corruption seeping into their minds, or in some cases - they willingly submitted.\n\nSuch great strength - snuffed out.\n\nAnd now, thanks to you, they preserve their final shred of valor. \n\nWithout you, the horrors of their deaths would outweigh the heroics of their lives.", sourceObjectiveStatus = "unverified-source-field" }
