quests[88718] = { id = 88718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never at Rest", description = "Bring me any doomed souls that cross your path, {name}.\n\nLet me rephrase that - you MUST bring them to me.\nMY duty is to stay and guide the souls of the lost. YOUR duty is to bring them to me.\n\nA word of advice, never handle more than one soul at a time. Trust me, your soul can only handle so much, and your mind... well... it can handle even less.\n\nThis burden is now yours. Because you can, you must. \n\nConsider this a moral obligation.", sourceObjective = "Bring another Heart of Doom to Brother Luctus at Light's Hope Chapel in Eastern Plaguelands.", progress = "The scourge never rests, so we must never rest, {name}.", completion = "{name}, with every heart returned, I stand humbled. Some of the souls have been from powerful warriors. Some seemed as though they were indomitable... and yet... they fell.\n\nScourge overrunning them, corruption seeping into their minds, or in some cases - they willingly submitted.\n\nSuch great strength - snuffed out.\n\nAnd now, thanks to you, they preserve their final shred of valor. \n\nWithout you, the horrors of their deaths would outweigh the heroics of their lives.", sourceObjectiveStatus = "unverified-source-field" }
quests[88721] = { id = 88721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superior Armaments of Battle - Friend of the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of power?\n\nI must warn you; purchases made at a friendly reputation with the Dawn come with a hefty surcharge. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.", sourceObjective = "For 30 Insignias of the Dawn and 30 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", progress = "Choose carefully. There are no refunds.", completion = "Good day, {name}. It was a pleasure doing business with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[88722] = { id = 88722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superior Armaments of Battle - Honored Amongst the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of power?\n\nI must warn you; purchases made at honored reputation with the Dawn come with a fairly prohibitive surcharge. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.", sourceObjective = "For 20 Insignias of the Dawn and 20 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", progress = "Choose carefully. There are no refunds.", completion = "Good day, {name}. It was a pleasure doing business with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[88723] = { id = 88723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superior Armaments of Battle - Revered Amongst the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of power?\n\nItems offered to those revered amongst the Dawn are priced quite reasonably. I encourage you to make a purchase!", sourceObjective = "For 7 Insignias of the Dawn and 7 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", progress = "Choose carefully. There are no refunds.", completion = "Good day, {name}. It was a pleasure doing business with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[88724] = { id = 88724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superior Armaments of Battle - Exalted Amongst the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of power?\n\nItems offered to those exalted amongst the Dawn are discounted. I encourage you to make a purchase!", sourceObjective = "For 6 Insignias of the Dawn and 6 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", progress = "Choose carefully. There are no refunds.", completion = "Good day, {name}. It was a pleasure doing business with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[88725] = { id = 88725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Epic Armaments of Battle - Friend of the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?\n\nI must warn you; purchases made at a friendly reputation with the Dawn come with an extremely hefty surcharge. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.You will be able to choose one of these rewards:", sourceObjective = "For 110 Insignias of the Dawn and 110 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", sourceObjectiveStatus = "unverified-source-field" }
quests[88726] = { id = 88726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Epic Armaments of Battle - Honored Amongst the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?\n\nI must warn you; purchases made at honored reputation with the Dawn come with an extremely hefty surcharge. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.You will be able to choose one of these rewards:", sourceObjective = "For 75 Insignias of the Dawn and 75 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", sourceObjectiveStatus = "unverified-source-field" }
quests[88727] = { id = 88727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Epic Armaments of Battle - Revered Amongst the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?\n\nI must warn you; epic purchases made at revered reputation with the Dawn are still quite expensive. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.", sourceObjective = "For 45 Insignias of the Dawn and 45 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", progress = "Choose carefully. There are no refunds.", completion = "Good day, {name}. It was a pleasure doing business with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[88728] = { id = 88728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Epic Armaments of Battle - Exalted Amongst the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?\n\nThose exalted amongst the Dawn receive our greatest discounts! I encourage you to make a purchase.", sourceObjective = "For 27 Insignias of the Dawn and 27 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", progress = "Choose carefully. There are no refunds.", completion = "Good day, {name}. It was a pleasure doing business with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[88729] = { id = 88729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ramaladni's Icy Grasp", description = "Fixing this band may prove to be quite challenging, {name}. You see, it was made from the very runes that form inside Scourge structures - like Naxxramas. Additional materials are also required but your main concern should be getting those frozen runes. Bring me what I need and I will restore the ring to its former glory.", sourceObjective = "Korfax at Light's Hope Chapel in the Eastern Plaguelands wants you to bring him 1 Frozen Rune, 1 Blue Sapphire and 1 Arcanite Bar.", progress = "Frozen runes could probably be found inside Naxxramas.", completion = "Ramaladni himself couldn't have done better! Here is the ring, as promised.", sourceObjectiveStatus = "unverified-source-field" }
quests[88730] = { id = 88730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Only Song I Know...", description = "You fancy yourself a hero of the Dawn, eh? I've seen our greatest soldiers get rolled over by Kel'Thuzad's plebes! How well could someone so clueless possibly fare in Naxxramas?\n\n<Wilhelm sighs.>\n\nBah, what choice do I got? You're the best I can do; I may as well help you.\n\nOmarion left me with one recipe. It's the only song I know... I can make a few variations of these pants; you just gotta supply the materials.", sourceObjective = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants you to bring him 2 Frozen Runes, 2 Essence of Water, 2 Blue Sapphires and 30 gold pieces.", progress = "You haven't run into Omarion, have you?", completion = "<Wilhelm wipes the sweat from his brow.>\n\nThat's some hard work! Enjoy the pants, {class}. At least you'll die in a clean pair now.", sourceObjectiveStatus = "unverified-source-field" }
quests[88744] = { id = 88744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Under the Shadow", description = "The floating necropolises of the Scourge plague the lands of Horde and Alliance alike. Tanaris, the Blasted Lands, Winterspring and the Burning Steppes are blanketed in the shadows of the flying fortresses.\n\nOnly through our combined efforts will they be turned away.\n\nThe necropolises are supported by magical circles at various points in the invaded areas. We have determined that destroying the mindless hordes that surround these circles will destroy their defenses.", sourceObjective = "Check your map to find an area under Scourge attack. Go there and damage a necropolis by defeating the Scourge around them. Return 10 of their Necrotic Runes to Commander Thomas Helleran at Light's Hope Chapel in the Eastern Plaguelands.", progress = "It will take time to prevail against this threat. How have you fared, {name}?", completion = "You've done well, {name}. Through these incremental defeats, we shall prevail against this renewed Scourge threat.\n\nRest and recover, but then you must head out to the front again, lest we lose the ground we have gained today.\n\nTo aid you in your further battles, we will make some of our special items available to you in trade for more necrotic runes.", sourceObjectiveStatus = "unverified-source-field" }
quests[88745] = { id = 88745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadows of Doom", description = "After you bring down the defenses of the Scourge summoning circles that have appeared in the zones under attack, you will be able to confront the acolytes who protect them.\n\nIn truth, these are not men. They are shadows, some of the Lich King's most frightening creatures. They can be revealed using the necrotic runes they carry, and then destroyed with magic or strength of arms.", sourceObjective = "Go to a summoning circle and kill a Shadow of Doom, then return to Commander Thomas Helleran at Light's Hope Chapel in Eastern Plaguelands.", progress = "Have you had any luck, {name}?", completion = "Excellent work, {name}. With the shadows destroyed, it can only be a matter of time before the Lich King decides to recall his necropolises and leave us in peace.", sourceObjectiveStatus = "unverified-source-field" }
quests[88746] = { id = 88746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consecrated Sharpening Stones", progress = "If you bring me eight necrotic runes from the Scourge invaders, I can give you a consecrated sharpening stone. It should be of great help in your battle against the minions of the Lich King.", completion = "Thank you, {name}. Here are your consecrated sharpening stones. Use them prudently." }
quests[88747] = { id = 88747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consecrated Sharpening Stones", progress = "If you bring me eight necrotic runes from the Scourge invaders, I can give you a consecrated sharpening stone. It should be of great help in your battle against the minions of the Lich King.", completion = "Thank you, {name}. Here are your consecrated sharpening stones. Use them prudently." }
quests[88748] = { id = 88748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cracked Necrotic Crystal", description = "On the corpse of the fallen abomination, you discover a cracked crystal, slowly pulsing with necrotic energy.", sourceObjective = "Bring the Cracked Necrotic Crystal to Lieutenant Orrin outside the gates of Stormwind.", progress = "Is there something you need?", completion = "Hm, you took this from the corpse of one of the invading abominations?\n\nWe have received word about the necropolis base camps that are being summoned by the Scourge. I suspect they wanted to create one inside Stormwind. It is good that they were unsuccessful.", sourceObjectiveStatus = "unverified-source-field" }
quests[88749] = { id = 88749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faint Necrotic Crystal", description = "On the corpse of the fallen wight, you find a crystal that is faintly radiating necrotic energy.", sourceObjective = "Bring the Faint Necrotic Crystal to Lieutenant Rukag in the courtyard of the Undercity.", progress = "Can I help you with something?", completion = "You say this was taken from a wight attacking the city?\n\nWe have received word about the necropolis base camps that are being summoned by the Scourge. I suspect they were trying to create one in the Undercity. We will have to be vigilant in the future.", sourceObjectiveStatus = "unverified-source-field" }
quests[88882] = { id = 88882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessed Wizard Oil", progress = "In exchange for the necrotic runes of the Scourge invaders, the Argent Dawn will give you one vial of blessed wizard oil.", completion = "I hope that you will find these items useful in future battles." }
quests[88883] = { id = 88883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessed Wizard Oil", progress = "In exchange for the necrotic runes of the Scourge invaders, the Argent Dawn will give you one vial of blessed wizard oil.", completion = "I hope that you will find these items useful in future battles." }
quests[88968] = { id = 88968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lord of Blackrock", description = "Seek out High Overlord Saurfang in the Valley of Strength.", sourceObjective = "Speak with High Overlord Saurfang in Orgrimmar. He stands waiting for you in the Valley of Strength.", completion = "Choose your reward so that I may mount the head of the beast for all to see.", sourceObjectiveStatus = "unverified-source-field" }
quests[88969] = { id = 88969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lord of Blackrock", description = "Go to the Valley of Heroes and speak with Field Marshal Stonebridge.", sourceObjective = "Venture to the Valley of Heroes in Stormwind City and speak with Field Marshal Stonebridge.", completion = "<Field Marshal Stonebridge bows.>\n\nChoose your reward, let the celebration begin!", sourceObjectiveStatus = "unverified-source-field" }
quests[89224] = { id = 89224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Food Shortage", description = "<The chef begins speaking before you could manage a simple greeting.>\n\nThank the light, help finally arrived! Neither the stove nor the pantry can keep up with the sudden surge in orders coming in. Something happened that cut off our usual supply lines, and I assume all the screaming outside has something to do with it.\n\nWhatever the reason, I need assistance. Now. Fetch me whatever looks vaguely edible from around town and we'll go from there.", sourceObjective = "Acquire Unappetizing Leftovers from across New Avalon and return them to the chef. If you are having trouble finding them scattered around, you may have better luck solving this shortage with violence.", progress = "Please leave me alone until you have gathered some ingredients.", completion = "Oh. Oh... I expected day-old bread, overripe fruit, and maybe a plate of half-eaten cookies or something.\n\nI truly have no clue what any of these dishes once were, and I made them! And that... smell... Are you trying to sabotage my kitchen?\n\nDeep breaths, Carrie...\n<The chef closes her eyes and inhales slowly through her nostrils, exhaling softly a moment later.>\n\nLet's try this again.", sourceObjectiveStatus = "unverified-source-field" }
quests[89229] = { id = 89229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Right Path", description = "Now you know the whole story. Reliving all of this was painful, but I've put off facing it for far too long. Strangely, I feel... better. I've prayed for justice for so long, but delivering that justice is not my burden to bear. I've chosen my own path and letting vengeance pull me back into darkness will not bring me peace, nor will it honor my son's wishes.\n\nI'm heading back to deliver my report to Lord Tyrosus. I'll see you back at Light's Hope. I have something for you there.", sourceObjective = "Speak with Leonid Barthalomew the Revered at Light's Hope Chapel to receive your reward.", completion = "Caldoran's reckoning will come eventually as his brand of evil is ultimately self-defeating. I have faith in that, just as I have faith in my son's dream. \n\nPlease, take this. This was given to me by Liliana when I was inducted into the Silver Hand and served me well as a reminder of my oaths to my family and country during my years of service. I hope it can serve as a reminder that it is always darkest before the dawn, but the dawn will always come.", sourceObjectiveStatus = "unverified-source-field" }
quests[89232] = { id = 89232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The First Step", description = "In Caldoran's hubris, he thought that he could force the blade to submit to his will. He stole the lives of his most fervently loyal followers to fuel his attempt to dominate the blade. What he didn't realize is that this power can't be taken by force; its cleansing must be earned. \n\nSpeak with me further if you wish to see the blade restored. If you are strong enough, you might just succeed.", sourceObjective = "Speak with the Will of the Ashbringer and hear what it has to say.", progress = "<The spectral outline of the Will of the Ashbringer shifts and shivers in an unsettling way.>", completion = "So now you see? You must see this through until the end, and that end is far from certain. If you would see this task completed, then you must have courage even in the face of that uncertainty. \n\nDo you have that courage?", sourceObjectiveStatus = "unverified-source-field" }
quests[89234] = { id = 89234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Personal Matter", description = "What we spoke about at Light's Hope and my history with Caldoran... It all started right here at Stratholme. You are familiar with the \"culling\" of Stratholme that occurred early on in the Third War, yes?\n\nWell, I was here, and so was Caldoran. This is where our history begins. If you would be willing, meet me just outside of Stratholme's service entrance to the east.", sourceObjective = "Meet Leonid Barthalomew the Revered just outside the service entrance gate to the east of the front gates of Stratholme.", completion = "I'm glad you came. I don't know if I'd be able to do what comes next alone.", sourceObjectiveStatus = "unverified-source-field" }
quests[89235] = { id = 89235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Culling", description = "The city behind us is a haunted place. I spent years here after my original death as a thrall of the Lich King yet even in my servitude, I maintained some amount of awareness. Countless times, I shambled by the body of my wife, frozen forever in the fear she felt when the end came. \n\nPlease make your way through gate leading to the area now known as Slaughter Square. I will meet you there when I find my resolve. You will need allies for this.", sourceObjective = "Enter Stratholme and make your way through the gate leading into Slaughter Square and find Leonid Barthalomew the Revered there.", completion = "So now you see why I despise Caldoran. He is a man of hateful zealotry. He was then, and he is now. Caldoran did not accompany Arthas's expedition to Northrend, but I dearly wish he had found his end there and this was the end of our history together.", sourceObjectiveStatus = "unverified-source-field" }
quests[89236] = { id = 89236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrangling Apples", description = "If you ask me, fresh fruit is the highlight of any meal. Apples are my favorite, and conveniently we have a thriving orchard south of here.\n\nAssuming it hasn't caught fire yet - which is a distinct possibility - I'll bet it's about time for a harvest!\n\nNormally the farmhands are willing to cut me a discount, but I still owe them a pie. Getting them for cheap is out of the question, but you look like you can afford them.", sourceObjective = "Locate the apple orchard in the southern section of New Avalon to fetch some apples. Return to Carrie Hearthfire in the New Avalon inn once you have succeeded. If you find the apples to be too expensive, consider looking around for an alternative means to acquire them.", progress = "Despite living a stone's throw away from an orchard, it is surprisingly difficult to get a hold of apples sometimes.", completion = "<Carrie carefully inspects each apple for imperfections. The silence, meanwhile, is long and awkward.>\n\nYou have an eye for quality when you aren't digging through the trash. These are the freshest apples I have seen since my younger days at the monastery!\n\nI must confess, I was ready to revoke your membership after your first delivery. Keep this up and I might have to offer you a full-time position instead.", sourceObjectiveStatus = "unverified-source-field" }
quests[89237] = { id = 89237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Could Get Expensive...", description = "In order to create this alloy, we'll need a lot of materials to experiment with. I've prepared a list and, well, I told you it might get expensive.\n\n<Omarion hands you a list that's nearly as long as your forearm.>", sourceObjective = "Bring Master Craftsman Omarion 20 Arcanite Bars, 20 Obsidian-Infused Thorium Bars, 120 Truesilver Bars, 10 Huge Emeralds, and 20 Righteous Orbs.", progress = "Listen, creating metallurgic miracles doesn't just happen by magic. You need time, patience, and someone with deep pockets.", completion = "Thinking about the cost of all of this makes my eyes water a bit. Oh well, nothing ventured, nothing gained.", sourceObjectiveStatus = "unverified-source-field" }
quests[89245] = { id = 89245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fish in a Barrel", description = "I served in Hearthglen for a time, and I cannot tell you how utterly terrifying it was relying on deliveries from across the Plaguelands to keep us fed. New Avalon having a stable supply chain by sea has been a blessing, at least until very recently.\n\nIn yet another case of \"Carrie is trying to feed an army with a kitchen stocked for a family\", I am in need of fish. Check the dock down south to see if my order has arrived.", sourceObjective = "Investigate the boat docked south of New Avalon for a shipment of fish and return a haul back to Carrie.", progress = "Did I mention that I hate the smell of fish? Maybe I should ask you to grab a clothespin while you're out.", completion = "I don't recognize a few of these, but a fish is a fish I suppose. Either way, I am already looking forward to having all of this out of my kitchen.\n\nThank you for your help, even if this was a task I actually hoped you would have returned empty handed.", sourceObjectiveStatus = "unverified-source-field" }
quests[89253] = { id = 89253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Main Course", description = "No meal is truly complete without the star of the dish - the meat! As you can probably imagine, hunting for meat that is safe to consume in the Plaguelands is a challenge unlike no other.\n\nTo make matters worse, our hounds eat nothing but meat! I am sure you can see where this is going, and I am sure by now you understand why I am perpetually behind.\n\nWell? What are you waiting for?", sourceObjective = "Acquire meat that is safe for human consumption. If you struggle to locate some in New Avalon, you may (eventually) gather enough from slaying beasts in the Eastern Plaguelands.", progress = "Back already? That can't be good.", completion = "Your expedience is appreciated and suspicious; almost as suspicious as the coloration of these hunks of meat. Fortunately we have all built up strong stomachs during our time out here.\n\nA few cuts here, a dash of spices there, and no one will be the wiser.\n\nThese will suffice, hopefully. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[89255] = { id = 89255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prove Your Worth: Headgear", description = "Staying on top of your trade is crucial for maintaining a high standard of quality. Our soldiers entrust their lives to unnamed craftsmen, and to me for ensuring the quality of every piece of armor.\n\nMy task for you is simple. If you are well practiced in Tailoring, Leatherworking, or Blacksmithing, then craft a piece of headgear, purely for your own benefit. You are free to keep the result.\n\nIf you lack the skill, commission and donate any piece of the crusade's uniform instead.", sourceObjective = "Craft a piece of Scarlet Headgear from any armor crafting profession or donate any piece of crafted Scarlet Uniform equipment. \n\nIf you choose to donate, you can find a crate near the quartermaster inside of the barracks. Deliver the crated item back to Bryon Steelblade to receive credit.", progress = "Craft or contribute; the choice is yours. Our armory is well equipped for whatever comes our way, but the important thing is ensuring our craftsmen have ample opportunities to practice and refine their technique.", completion = "Excellently done.\n\nWe have started stashing confiscated junk in these old trunks and I am running out of space to store them now, but you seem the sort to take value in the little things. I believe this is an appropriate reward for a single contribution.\n\nOh, and I added a valuable surprise into a few of these. Maybe you'll be one of the lucky ones?", sourceObjectiveStatus = "unverified-source-field" }
quests[89256] = { id = 89256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prove Your Worth: Shoulderpads", description = "Staying on top of your trade is crucial for maintaining a high standard of quality. Our soldiers entrust their lives to unnamed craftsmen, and to me for ensuring the quality of every piece of armor.\n\nMy task for you is simple. If you are well practiced in Tailoring, Leatherworking, or Blacksmithing, then craft a pair of shoulderpads, purely for your own benefit. You are free to keep the result.\n\nIf you lack the skill, commission and donate any piece of the crusade's uniform instead.", sourceObjective = "Craft a piece of Scarlet Shoulders from any armor crafting profession or donate any piece of crafted Scarlet Uniform equipment. \n\nIf you choose to donate, you can find a crate near the quartermaster inside of the barracks. Deliver the crated item back to Bryon Steelblade to receive credit.", progress = "Craft or contribute; the choice is yours. Our armory is well equipped for whatever comes our way, but the important thing is ensuring our craftsmen have ample opportunities to practice and refine their technique.", completion = "Excellently done.\n\nWe have started stashing confiscated junk in these old trunks and I am running out of space to store them now, but you seem the sort to take value in the little things. I believe this is an appropriate reward for a single contribution.\n\nOh, and I added a valuable surprise into a few of these. Maybe you'll be one of the lucky ones?", sourceObjectiveStatus = "unverified-source-field" }
